import {BackendService} from "../../common/my-service-protocol";

export interface LoggerServices {
  backend: BackendService;
}


export class LoggerManager {
  private static _instance: LoggerManager;

  protected backendService: BackendService;

  private constructor(services: LoggerServices) {
    this.backendService = services.backend;
  }

  public static getInstance(services?: LoggerServices) {
    if (services && services.backend && !this._instance) {
      this._instance = new LoggerManager(services);
      console.log("creating instance of LOGGERMANAGER");
    }

    if (this._instance) {
      return this._instance;
    } else {
      return undefined;
    }

  }

  public info(message: string, component: string = 'theia-sn-extension') {
    this.backendService.log_info(message, component)
  }

  public error(message: string, component: string = 'theia-sn-extension') {
    this.backendService.log_error(message, component)
  }

  public debug(message: string, component: string = 'theia-sn-extension') {
    this.backendService.log_debug(message, component)
  }

  public warn(message: string, component: string = 'theia-sn-extension') {
    this.backendService.log_warn(message, component)
  }

}
