import React = require('react');
import { HelperService } from '../../helper-service';
import {LoggerManager} from "../../managers/logger-manager";

/**
 * Database subheading props.
 * @property {string} appId - Application id.
 * @property {boolean} hasAdminApp - True if the database has an admin app, else False.
 * @property {boolean} hasDatabaseServer - True if the database has a database server, else False.
 * @property {{ [key: string]: string } | undefined} versionDict - Dictionary of versions to be displayed. Currently
 * supports "server", "web", and "shell".
 * @property {string} description - Application description.
 */
export interface ApplicationSubheadingProps {
  appId: string;
  hasAdminApp: boolean;
  hasDatabaseServer: boolean;
  versionDict: { [key: string]: string } | undefined;
  description: string;
}

export class DatabaseSubheading extends React.Component<ApplicationSubheadingProps> {

  render(): React.ReactNode {
    if (this.props.versionDict) {
      let databaseServerIcon: any = "";
      if (this.props.hasDatabaseServer) {
        databaseServerIcon = <span className="db-info" title="Database server version"
          onClick={async () => this.openDetailsPanel("dbServer")}>
          <span className="subheading-icon database"></span>
          {this.props.versionDict["server"]}
        </span>
      }

      let adminIcon: any = "";
      if (this.props.hasAdminApp) {
        adminIcon = <span className="db-info" title="Administration tool version"
          onClick={async () => this.openDetailsPanel("admin")}>
          <span className="subheading-icon admin"></span>
          {this.props.versionDict["web"]}
        </span>
      }

      return <div className="subheading">
        {databaseServerIcon}
        {adminIcon}
        <span className="db-info" title="Command-line interface version" onClick={async () => this.openDetailsPanel("cli")}>
          <span className="subheading-icon cli"></span>
          {this.props.versionDict["shell"]}
        </span>
        <div className="db-description">{this.props.description}</div>
      </div>
    } else {
      return null
    }
  }

  private async openDetailsPanel(subheading: string) {
    // Navigate to Details tab panel.
    HelperService.openTabPanel("Details", this.props.appId)
    // Get appropriate subheading elements in Details.
    let headingText = document.getElementById(subheading + this.props.appId);
    let headingIcon = document.getElementById(subheading + "Icon" + this.props.appId);
    if (headingText && headingIcon) {
      // Change color of subheading from blue back to default after 0.6 seconds.
      headingIcon.style.backgroundColor = "#3B8DEA";
      headingText.style.color = "#3B8DEA";
      await new Promise(resolve => setTimeout(resolve, 500));
      headingText.animate([
        { color: "#3B8DEA" },
        { color: 'var(--theia-foreground)' }
      ], {
        duration: 600,
        iterations: 1
      })
      headingIcon.animate([
        { backgroundColor: "#3B8DEA" },
        { backgroundColor: 'var(--theia-foreground)' }
      ], {
        duration: 600,
        iterations: 1
      })
      headingText.style.color = "var(--theia-foreground)";
      headingIcon.style.backgroundColor = "var(--theia-foreground)";
    } else {
      LoggerManager.getInstance()?.info("details subheading not found")
    }
  }

}
