import React = require('react');
import { TerminalService } from '@theia/terminal/lib/browser/base/terminal-service';
import { MessageService } from '@theia/core';
import { TerminalWidget } from '@theia/terminal/lib/browser/base/terminal-widget';
import { Status } from "../Status";
import { LoggerManager } from '../../managers/logger-manager';


/**
 * Access button props.
 * @property {Status} status - Affects if button is disabled or loading.
 * @property {string} cliName - Title of button that gives access to the command line interface (CLI).
 * @property {string} appName - Name of application.
 * @property {TerminalService} terminalService
 * @property {MessageService} messageService
 * @property {string | undefined} startCommand - Command line prompt to start up application.
 * @property {boolean | undefined} hideNewTerminal - Show the New Terminal Button
 */
export interface AccessButtonsProps {
  status: Status;
  cliName: string;
  appName: string;
  terminalService: TerminalService;
  messageService: MessageService;
  startCommand: string;
  hideNewTerminal?: boolean;
}

export class AccessButtons extends React.Component<AccessButtonsProps> {

  private accessErrorMessage: string = "Terminal could not be started.";
  private isDisabled: boolean;

  render(): React.ReactNode {
    const isLoading: boolean = (this.props.status === Status.STARTING || this.props.status === Status.RESTORING) ? true : false;
    this.isDisabled = (this.props.status != Status.ACTIVE) ? true : false;

    if (this.props.hideNewTerminal) {
      if (isLoading) {
        return <div className="button-container">
          <button className='theia-button primary loading'>{this.props.cliName}</button>
        </div>
      } else {
        return <div className="button-container">
          <button className='theia-button primary' title={this.props.appName + " command line interface"}
            onClick={_a => this.openTerminal(true)}>{this.props.cliName}</button>
        </div>
      }
    } else {
      if (isLoading) {
        return <div className="button-container">
          <button className='theia-button primary loading'>{this.props.cliName}</button>
          <button className='theia-button primary loading'>New Terminal</button>
        </div>
      } else {
        return <div className="button-container">
          <button className='theia-button primary' title={this.props.appName + " command line interface"}
            onClick={_a => this.openTerminal(true)}>{this.props.cliName}</button>
          <button className='theia-button primary' title='Open new terminal' onClick={_a => this.openTerminal(false)}>New Terminal</button>
        </div>
      }
    }
  }

  /**
   * Open a terminal in the IDE and optionally send a command.
   * Note that this is generally not recommended, as there is no way to confirm if the command successfully occurred.
   * Until Theia updates their source code, the fix right now is to set a timeout, u
   * @param sendCommand - True if you would like to send <this.props.startCommand> to terminal.
   */
  protected async openTerminal(sendCommand: boolean): Promise<void> {
    if (this.isDisabled || this.props.cliName === undefined) {
      this.props.messageService.error(this.accessErrorMessage);
    } else {
      try {
        let terminalWidget = sendCommand ? await this.props.terminalService.newTerminal({ title: this.props.cliName }) :
          await this.props.terminalService.newTerminal({}); // if opening database CLI, pass in database title as terminal title
        await terminalWidget.start();
        this.props.terminalService.open(terminalWidget);
        if (sendCommand) {
          this.sendTerminalCommand(terminalWidget);
        }
      } catch (e) {
        this.props.messageService.error(this.accessErrorMessage);
        LoggerManager.getInstance()?.error(e);
      }
    }
  }

  private async sendTerminalCommand(terminalWidget: TerminalWidget): Promise<void> {
    try {
      await new Promise(resolve => setTimeout(resolve, 600)); // set timeout, otherwise command arrives faster than backend manages to write something to the shell
      terminalWidget.sendText(this.props.startCommand);
      terminalWidget.sendText('\n');
    } catch {
      throw new TypeError("startCommand is undefined");
    }
  }

}
