  constructor() {
    super();
    this.storedStatus = {};
    // Get data of all apps from config file
    this.applications = { database: [], bigData: [], cloud: [] }; // Add app categories that you'd like to show
    const categories = Object.keys(this.applications);
    const apps: any = config.applicationDetails;
    for (let app in apps) {
      // @ts-ignore
      // For each app, determine if its category fits under one you'd like to show
      const category: string = apps[app]["category"];
      if (categories.includes(category)) {
        // If yes, create a dict containing its info and push it into list of apps under that category
        const appInfo = this.getStaticAppInfo(app);
        this.applications[category].push(appInfo);
      }
    }

    // Now setup embeddable AI components
    this.embeddableAIComponents = [];
    const components: [any] = apps["embeddableAI"].components;
    for (let component of components) {
      this.embeddableAIComponents.push(component as EmbeddableAIComponentInfo);
    }
  }

