  private createSidebarButtons(
    category: string,
    array: JSX.Element[],
    allowInRegular: boolean = false
  ) {
    // Loop through app data and check if any app id cooresponds to any tab pages that are open
    const isDisabled: boolean =
      this.environment === Environment.THEIA && !allowInRegular;

    for (let app of this.applications[category]) {
      // Create a reference to the React component and store it for future use
      let reference = React.createRef<SidebarAppButton>();

      // Set the status in priority order
      let status: Status;
      if (isDisabled) {
        status = Status.DISABLED;
      } else {
        if (this.appShell.getWidgetById(app.id) instanceof DatabaseTab) {
          let tab = this.appShell.getWidgetById(app.id) as DatabaseTab;
          status = tab.appStatus;
        } else {
          status = this.appManager.includesAppStatus(app.id)
            ? this.appManager.getStatus(app.id)
            : Status.INACTIVE;
        }

        // TODO handle DISABLED better
        if (status === Status.DISABLED) {
          console.log(
            `Environment is not Cloud IDE Basic and app is disabled - Env ${this.environment} - App ${app.id}`
          );
          status = this.appManager.fixStatus(app.id);
        }
      }

      // Create React component
      array.push(
        <SidebarAppButton
          ref={reference}
          key={app.id}
          name={app.name}
          status={status}
          appId={app.id}
          description={app.description}
          onClick={() => {
            this.openApplicationTab(app.id, app.category);
          }}
          messageService={this.messageService}
          commandReg={this.commandRegistry}
        />
      );

      // Add application to manager
      this.appManager.addApplication(app.id, app, status, reference);

      // If app status is RESTORING, call verifyActive right away
      if (status === Status.RESTORING) {
        this.appManager.verifyActive(app.id);
      }
    }
  }

