import * as React from 'react';
import * as ReactDOM from 'react-dom';
import { TabPageWidget } from "./tab-page-widget";
import { Status } from "./Status";
// import { ApplicationTabPanel } from './components/application-tab-panel';
// import { DatabaseSubheading } from './components/database-subheading';
import { Message } from '@theia/core/lib/browser';
import { HelperService } from '../helper-service';
import { ApplicationManager } from '../managers/application-manager';
import { LoggerManager } from "../managers/logger-manager";

import { CopyText } from './components/copy-text';

function camelize(str: string) {
  return str.replace(/(?:^\w|[A-Z]|\b\w|\s+)/g, function(match, index) {
    if (+match === 0) return ""; // or if (/\s+/.test(match)) for white spaces
    return index === 0 ? match.toLowerCase() : match.toUpperCase();
  });
}


export interface EmbeddableAIComponentInfo {
  id: string;
  name: string;
  description: string;
  category: string;
  enabled: boolean;
  hostname: string;
  grpcHostname: string;
  image: string;
  models: { id: string; lang: string; description?: string; sampleURL?: string }[];
  examples: { name: string; description: string; command: string }[];
  apiDoc: string;
}

export interface EmbeddableAIExample {
  name: string;
  description: string;
  command: string;
}

export class EmbeddableAITab extends TabPageWidget {

  static readonly childID = 'embeddableai-tab:widget';

  protected appId: string;
  protected status: Status;
  protected applicationInfo: EmbeddableAIComponentInfo;
  protected manager: ApplicationManager;

  protected internalButtonRef: React.RefObject<HTMLButtonElement> = HelperService.setRef();

  set appInfo(info: EmbeddableAIComponentInfo) {
    this.applicationInfo = info;
  }

  set applicationId(id: string) {
    this.appId = id;
  }

  set appStatus(newStatus: Status) {
    this.status = newStatus;
  }

  set appManager(manager: ApplicationManager) {
    this.manager = manager;
  }

  get appStatus(): Status {
    return this.status
  }

  storeState(): object | undefined {
    return {
      appId: this.appId,
      status: this.status,
      applicationInfo: this.applicationInfo,
      tabTitle: this.applicationInfo.name,
      tabId: this.appId,
      icon: this.title.iconClass,
    };
  }

  restoreState(oldState: object): void {
    const state = oldState as {
      appId: string,
      status: Status,
      applicationInfo: EmbeddableAIComponentInfo,
      tabTitle: string,
      tabId: string,
      icon: string,
    };
    this.appId = state.appId;
    this.status = state.status;
    this.applicationInfo = state.applicationInfo;
    this.title.label = state.tabTitle;
    this.id = state.tabId;
    this.title.iconClass = state.icon;
    this.manager = ApplicationManager.getInstance({
      backend: this.backendService,
      shell: this.appShell,
      messaging: this.messageService,
      varResolver: this.varResolver,
      window: this.windowService
    });
  }


  protected async openLinkInNewTab(value: string) {
    try {
      await HelperService.previewExternally(value, this.varResolver, this.windowService);        
    } catch (e) {
        this.messageService.error("There was an error opening this link.");
        LoggerManager.getInstance()?.error(e);
    }
  }

 

  /**
   * Updates the tab to reflect a change in database status.
   */
  public async reloadTab(newStatus: Status): Promise<void> {
    // ReactDOM.render(<React.Fragment>{this.render()}</React.Fragment>, this.node, () => this.onRender.dispose());
    ReactDOM.render(<React.Fragment>{this.render()}</React.Fragment>, this.node);

  }

  /**
   * Overrides abstract render() method in TabPageWidget.
   */
  protected render(): React.ReactNode {
    // For each piece of info in the app's connection information, create a copy container.
    let exampleCommands: JSX.Element[] = [];
    let exampleModels: JSX.Element[] = [];
    let exampleHostnames: JSX.Element[] = [];

    for (const example of this.applicationInfo.examples) {
      const key = camelize(example.name);
      exampleCommands.push(
        <CopyText key={key+'-copy'} status={Status.ACTIVE} label={example.name} value={example.command} applicationId={this.applicationInfo.id}
          messageService={this.messageService} 
          hasTerminal={true} terminalService={this.terminalService} />
      );
    }
    for (const model of this.applicationInfo.models) {
      exampleModels.push(<li>
          <div className="info-bar">
            <span className="info-name">{model.id}</span>
            <div className="copy-container">
              <p>{"Lang: " + model.lang}</p>
              {model.description && <p>{"Description: " + model.description}</p>}
              {model.sampleURL && <p><audio src={model.sampleURL} controls></audio></p>}
            </div>
          </div>
        </li>
      );
    }

    exampleHostnames.push(<CopyText key={'hostname-copy'} status={Status.ACTIVE} label={'REST Hostname'} value={'https://'+this.applicationInfo.hostname} applicationId={this.applicationInfo.id}
      messageService={this.messageService} hasTerminal={false} />);
    exampleHostnames.push(<CopyText key={'grpc-hostname-copy'} status={Status.ACTIVE} label={'GRPC Hostname'} value={this.applicationInfo.grpcHostname} applicationId={this.applicationInfo.id}
      messageService={this.messageService} hasTerminal={false} />);

    return (<div id='tab-container'>
      {/* HEADER */}
      <div className="sn-tool-header">
        <div className="title-container">
          <h1>{this.applicationInfo.name}</h1>
        </div>

        <div id={"Summary" + this.appId}>
          {this.applicationInfo.description}
        </div>
        <div>
          <p>
            <button className='theia-button primary' title='Open API Docs'
              onClick={async (_a) => this.openLinkInNewTab(this.applicationInfo.apiDoc)}>Open API Docs
              <span className="external-link-icon"></span>
            </button>
          </p>
        </div>
      </div>

      {/* HOSTNAMES */}
      <div id={"Hostnames" + this.appId} className={"tab-panel " + this.appId}>
        <h2>Hostnames</h2>
        <ul>
          {exampleHostnames}
        </ul>
      </div>

      {/* MODELS */}
      <div id={"Models" + this.appId} className={"tab-panel " + this.appId}>
        <h2>Models</h2>
        <ul>
          {exampleModels}
        </ul>
      </div>

      {/* EXAMPLES */}
      <div id={"Examples" + this.appId} className={"tab-panel " + this.appId}>
        <h2>Examples</h2>
        {exampleCommands}
      </div>

    </div>)
  }

  /** Before closing, change state if appropriate. */
  protected onCloseRequest(msg: Message): void {
    super.onCloseRequest(msg);
  }

}
