import React = require('react');
import { ApplicationManager } from '../../managers/application-manager';
import { Status } from "../Status";
import { LoggerManager } from "../../managers/logger-manager";

/**
 * Start Button props 
 */
export interface StopButtonProps {
  id: string;
  name: string;
  status: Status;
  manager: ApplicationManager;
  altButtonText: { [key: string]: string } | undefined;
}

export class StopButton extends React.Component<StopButtonProps> {
  render(): React.ReactNode {
    let label: string;
    let action: string = "stop";
    let disabled: boolean;

    switch (this.props.status) {
      case Status.ACTIVE:
      case Status.IDLE:
        label = this.props.altButtonText?.active || "Delete";
        disabled = false;
        break;
      case Status.STOPPING:
        label = this.props.altButtonText?.stopping || "Delete";
        disabled = true;
        break;
      default:
        label = this.props.altButtonText?.active || "Delete";
        disabled = true;
        break;
    }
    let hoverTitle: string = `${label} ${this.props.name}`;
    return <button className={'theia-button primary action-'+action} id={'stop-button'+this.props.id} disabled={disabled}
      title={hoverTitle} onClick={async (_a) => this.stopApp()}>{label}</button>
  }

  /**
   * Starts the application
   */
  protected async stopApp(): Promise<void> {
    await this.props.manager.stopApplication(this.props.id)
      .then(() => LoggerManager.getInstance()?.info(`${this.props.name} was successfully stopped`))
      .catch((e) => LoggerManager.getInstance()?.error(`Failed to stop ${this.props.name}: ${e}`));
  }
}