export enum Environment {
  UNKNOWN,
  THEIA,
  KUBERNETES,
  OPENSHIFT
}

export namespace Environment {

  export function getPath(env: Environment): string {
    switch (env) {
      case Environment.KUBERNETES:
        return "cloud-ide-kubernetes"
      case Environment.OPENSHIFT:
        return "cloud-ide-openshift"
      default:
        return "theia"
    }
  }

  export function fromString(env: string): Environment {
    switch (env.toLowerCase()) {
      case "docker":
      case "kubernetes":
        return Environment.KUBERNETES
      case "openshift":
        return Environment.OPENSHIFT
      default:
        return Environment.THEIA
    }
  }

  export function toString(env: Environment): string {
    switch (env) {
      case Environment.KUBERNETES:
        return "Kubernetes"
      case Environment.OPENSHIFT:
        return "OpenShift"
      default:
        return "Cloud IDE Basic"
    }
  }

}
