import * as React from 'react';
import { injectable, inject, postConstruct } from 'inversify';
import { ReactWidget } from '@theia/core/lib/browser/widgets/react-widget';
import { ApplicationShell, Message, StatefulWidget } from '@theia/core/lib/browser';
import { MessageService } from '@theia/core';
import { WindowService } from '@theia/core/lib/browser/window/window-service';
import { VariableResolverService } from '@theia/variable-resolver/lib/browser';
import { MiniBrowserOpenHandler } from '@theia/mini-browser/lib/browser/mini-browser-open-handler';
import { TerminalService } from '@theia/terminal/lib/browser/base/terminal-service';
import { BackendService } from '../../common/my-service-protocol';

/** Makes child instances TabPageWidget unique by allowing us to set a unique tabId. */
export interface TabPageWidgetOptions {
  tabId: string;
}

/** Collection of common Theia services. */
export interface TheiaServices {
  miniBrowserHandler: MiniBrowserOpenHandler;
  varResolver: VariableResolverService;
  appShell: ApplicationShell;
  messageService: MessageService;
  windowService: WindowService;
  terminalService: TerminalService;
}


@injectable()
export abstract class TabPageWidget extends ReactWidget implements StatefulWidget {

  static readonly ID = 'tab-page:widget';
  static readonly LABEL = 'Open tab'; // Over-write for child tabs
  protected theiaServices: TheiaServices;

  @inject(MiniBrowserOpenHandler)
  protected readonly miniBrowserHandler: MiniBrowserOpenHandler;

  @inject(VariableResolverService)
  protected readonly varResolver: VariableResolverService;

  @inject(ApplicationShell)
  protected readonly appShell: ApplicationShell;

  @inject(MessageService)
  protected readonly messageService!: MessageService;

  @inject(WindowService)
  protected readonly windowService: WindowService;

  @inject(TerminalService)
  protected readonly terminalService: TerminalService;

  @inject(BackendService)
  protected readonly backendService: BackendService;

  @postConstruct()
  protected init(): void {
    this.doInit();   
  }

  protected async doInit(): Promise<void> {
    this.id = TabPageWidget.ID;
    this.title.label = TabPageWidget.LABEL;
    this.title.caption = TabPageWidget.LABEL;
    this.title.closable = true;
    this.title.iconClass = 'fa fa-window-restore';
    this.theiaServices = {
      miniBrowserHandler: this.miniBrowserHandler,
      varResolver: this.varResolver,
      appShell: this.appShell,
      messageService: this.messageService,
      windowService: this.windowService,
      terminalService: this.terminalService,
    }
    this.update();
  }

  storeState(): object | undefined {
    return {
      id: this.id,
      title: this.title.label,
      icon: this.title.iconClass
    };
  }

  restoreState(oldState: object): void {
    const state = oldState as {
      id: string,
      title: string
      icon: string
    };
    this.id = state.id;
    this.title.label = state.title;
    this.title.caption = state.title;
    this.title.iconClass = state.icon;
  }

  set storedId(id: string) {
    this.id = id;
  }

  set tabTitle(title: string) {
    this.title.label = title;
  }

  set icon(name: string) {
    this.title.iconClass = name;
  }

  /**
   * Abstract render class to be implemented by TabPageWidget children.
   */
  protected abstract render(): React.ReactNode;

  /**
   * Give focus to tab widget. Gets rid of "Widget was activated, but did not accept focus after 2000ms" warning.
   */
  protected onActivateRequest(msg: Message): void {
    super.onActivateRequest(msg);
    this.node.tabIndex = 0;
    this.node.focus();
  }

  /**
   * Do stuff after the tab has been activated for the first time. Default implementation is void.
   */
  onFirstActivateRequest(): void { };
}
