:root {
  --theia-branding-logo: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
  --sn-toolbox-logo: url(${___CSS_LOADER_URL_REPLACEMENT_1___});
}

.gs-blue-header {
  color: #5088e7;
  text-transform: capitalize;
  font-weight: 600;
}

.gs-text-bold {
  font-weight: 600;
}

.gs-text-underline {
  text-decoration: underline;
}

.gs-float {
  float: right;
}

.gs-logo {
  background-image: var(--theia-branding-logo);
  background-position: center center;
  background-repeat: no-repeat;
  background-size: contain;
  width: 250px;
  height: 118px;
  padding: 20px;
}

.gs-section {
  margin: 10px;
}
/* 1. Override the outer overlay */
div#theia-dialog-shell.p-Widget.dialogOverlay {
  /* Force positioning and sizing */
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  z-index: 9999 !important;

  /* Center the dialog content */
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;

  /* Some padding to avoid content flush against edges */
  padding: 10px !important;
  box-sizing: border-box !important;
}

/* 2. Override the .dialogBlock styles */
div#theia-dialog-shell.p-Widget.dialogOverlay .dialogBlock {
  /* Constrain the dialog width/height so it doesn't overflow the screen */
  max-width: 90vw !important;
  max-height: 90vh !important;

  /* Make it scroll if content exceeds max height/width */
  overflow: auto !important;

  /* Optional: give the dialog block a white background & padding */
  padding: 10px !important;
  box-sizing: border-box !important;
}

/* 3. Ensure text wraps properly instead of overflowing */
div#theia-dialog-shell.p-Widget.dialogOverlay .dialogBlock,
div#theia-dialog-shell.p-Widget.dialogOverlay .dialogContent {
  white-space: normal !important;
  word-break: break-word !important;
}

/* 4. (Optional) Adjust font sizes for small screens */
@media (max-width: 600px) {
  /* Scale down fonts inside the overlay on narrow viewports */
  div#theia-dialog-shell.p-Widget.dialogOverlay,
  div#theia-dialog-shell.p-Widget.dialogOverlay * {
    font-size: 14px !important;
    line-height: 1.4 !important;
  }

  /* Narrow the dialog block further on very small screens */
  div#theia-dialog-shell.p-Widget.dialogOverlay .dialogBlock {
    max-width: 95vw !important;
    max-height: 85vh !important;
  }
}

.ad-logo {
  background-image: var(--theia-branding-logo);
  background-position: center center;
  background-repeat: no-repeat;
  background-size: contain;
  width: 250px;
  height: 118px;
  padding: 20px;
}

.sn-toolbox-logo {
  background-image: var(--sn-toolbox-logo);
  background-position: center center;
  background-repeat: no-repeat;
  background-size: contain;
  margin-inline: 4px;
  width: 32px;
  height: 32px;
}

.ad-float {
  float: right;
}

.ad-container {
  padding: 20px;
  width: 1150px;
  height: 700;
}

ul.theia-aboutExtensions {
  height: 450px;
  overflow: hidden;
  overflow-y: scroll;
  list-style-type: none;
  padding: 0;
  margin-left: 10px;
}
