import { interfaces } from 'inversify';
import { bindViewContribution, FrontendApplicationContribution, WidgetFactory } from '@theia/core/lib/browser';

import '../../../src/browser/tab-page/style/index.css';
import { TabPageContribution } from './tab-page-contribution';
import { TabPageWidget } from './tab-page-widget';
import { DatabaseTab } from './database-tab';
import { LaunchApplicationTab } from './launch-application-tab';
import { EmbeddableAITab } from './embeddable-ai-tab';
import { OpenLinkTab } from './open-link-tab';

export function bindTabPageModule(bind: interfaces.Bind) {
    bindViewContribution(bind, TabPageContribution);
    bind(FrontendApplicationContribution).toService(TabPageContribution);
    bind(TabPageWidget).toSelf();
    bind(WidgetFactory).toDynamicValue(ctx => ({
        id: TabPageWidget.ID,
        createWidget: () => ctx.container.get(TabPageWidget)
    })).inSingletonScope();

    // Whenever you create a new child class of TabPageWidget, make sure to bind it here. You will need to give the
    // class a unique "static readonly childID" property to set as the factory id.
    bind(OpenLinkTab).toSelf();
    bind(WidgetFactory).toDynamicValue(ctx => ({
        id: OpenLinkTab.childID,
        createWidget: () => ctx.container.get(OpenLinkTab)
    })).inSingletonScope();

    bind(LaunchApplicationTab).toSelf();
    bind(WidgetFactory).toDynamicValue(ctx => ({
      id: LaunchApplicationTab.childID,
      createWidget: () => ctx.container.get(LaunchApplicationTab)
    })).inSingletonScope();

    bind(DatabaseTab).toSelf();
    bind(WidgetFactory).toDynamicValue(ctx => ({
        id: DatabaseTab.childID,
        createWidget: () => ctx.container.get(DatabaseTab)
    })).inSingletonScope();

    bind(EmbeddableAITab).toSelf();
    bind(WidgetFactory).toDynamicValue(ctx => ({
        id: EmbeddableAITab.childID,
        createWidget: () => ctx.container.get(EmbeddableAITab)
    })).inSingletonScope();
}
