.multi-select-bar {
  display: flex;
  flex-flow: row nowrap;
  user-select: none;
  box-sizing: border-box;
}

.multi-select-checkbox-wrapper {
  display: flex;
  position: relative;
  flex: auto;
  text-align: center;
}

.multi-select-label {
  height: 100%;
  flex: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid;
  padding: 0 var(--theia-ui-padding);
  background-color: var(--theia-editor-background);
  border-color: var(--theia-dropdown-border);
  box-sizing: border-box;
}

.multi-select-checkbox-wrapper input:checked ~ .multi-select-label {
  background-color: var(--theia-input-background);
  border-color: var(--theia-sideBar-foreground);
  text-decoration: underline;
  font-weight: bolder;
}

.multi-select-checkbox {
  appearance: none;
  -webkit-appearance: none;
  position: absolute;
  left: 0;
  top: 0;
  margin: 0;
  height: 100%;
  width: 100%;
  cursor: pointer;
}
