import React = require('react');
import { ApplicationManager } from '../../managers/application-manager';
import { Status } from "../Status";
import { LoggerManager } from "../../managers/logger-manager";

/**
 * Start Button props 
 */
export interface StartButtonProps {
  id: string;
  name: string;
  status: Status;
  manager: ApplicationManager;
  altButtonText: { [key: string]: string } | undefined;
}

export class StartButton extends React.Component<StartButtonProps> {
  render(): React.ReactNode {
    let label: string = this.props.altButtonText?.inactive || "Create";
    let action: string = "start";
    let disabled: boolean;

    switch (this.props.status) {
      case Status.INACTIVE:
      case Status.ERROR:
        disabled = false;
        break;
      default:
        disabled = true;
        break;
    }
    let hoverTitle: string = `${label} ${this.props.name}`;
    return <button className={'theia-button primary action-'+action} id={'start-button'+this.props.id} disabled={disabled}
      title={hoverTitle} onClick={async (_a) => this.startApp()}>{label}</button>
  }

  /**
   * Starts the application
   */
  protected async startApp(): Promise<void> {
    await this.props.manager.startApplication(this.props.id)
      .then(() => LoggerManager.getInstance()?.info(`${this.props.name} was successfully started`))
      .catch((e) => LoggerManager.getInstance()?.error(`Failed to start ${this.props.name}: ${e}`));
  }
}