import React = require('react');
import { MessageService } from '@theia/core';
import { TerminalService } from '@theia/terminal/lib/browser/base/terminal-service';
import { Status } from "../Status";

/**
 * Copy text props.
 * @property {Status} status - Affects whether copy text containers are hidden or loading.
 * @property {string} label - Title of what is being copied.
 * @property {string | undefined} value - Value to copy.
 * @property {string} applicationId
 * @property {MessageService} messageService
 */
export interface CopyTextProps {
  status: Status;
  label: string;
  value?: string;
  hasTerminal?: boolean;
  applicationId: string;
  messageService: MessageService;
  terminalService?: TerminalService;
}

export class CopyText extends React.Component<CopyTextProps> {

  render(): React.ReactNode {
    let isHidden: boolean;
    let isLoading: boolean;
    switch (this.props.status) {
      case Status.ACTIVE:
      case Status.STOPPING:
        isHidden = false;
        isLoading = false;
        break;
      case Status.STARTING:
      case Status.RESTORING:
        isHidden = false;
        isLoading = true;
        break;
      default: // inactive and error
        isHidden = true;
        isLoading = false;
        break;
    }

    if (isHidden) {
      return null
    } else if (isLoading) {
      return <div className="info-bar">
        <span className="info-name">{this.props.label + ":"}</span>
        <div className="copy-container" style={{ animation: "pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite" }}></div>
      </div>
    } else {
      let terminalButton: any = <span className="cli-icon" title="Run in Terminal" onClick={_a => this.executeCode(this.props.label + this.props.applicationId)}></span>
      return <div className="info-bar">
        <span className="info-name">{this.props.label + ":"}</span>
        <div className="copy-container">
          <p className="code-container">{this.props.value}</p>
          <textarea readOnly id={this.props.label + this.props.applicationId} value={this.props.value}></textarea>
          <span className="copy-icon" title="Copy" onClick={_a => this.copyText(this.props.label + this.props.applicationId)}></span>          
          {this.props.hasTerminal && terminalButton}
        </div>
      </div>
    }
  }

  /**
   * Copy the value of an HTMLTextAreaElement to the clipboard.
   * @param id - Id of element.
   */
  protected copyText(id: string): void {
    let copyText = document.getElementById(id) as HTMLTextAreaElement;
    if (copyText == null) {
      this.props.messageService.warn("Invalid copy.");
    } else {
      copyText.select()
      copyText.setSelectionRange(0, 99999); // for mobile devices
      document.execCommand("copy");
      this.props.messageService.info("Copied to clipboard!");
    }
  }

  protected async executeCode(id: string) {
    const copyText = document.getElementById(id) as HTMLTextAreaElement;
    const command = copyText.value;

    if (this.props.terminalService) {
      let term = this.props.terminalService.lastUsedTerminal;
      if (!term) {
        term = await this.props.terminalService.newTerminal({})
        await term.start()
      }
      this.props.terminalService.open(term)
      term.sendText(command)
      term.sendText('\n');
    } else {
      this.props.messageService.warn("No Terminal Service.");
    }
  }

}
