import React = require('react');
import { HelperService } from '../../helper-service';
import { VariableResolverService } from '@theia/variable-resolver/lib/browser';
import { MiniBrowserOpenHandler } from '@theia/mini-browser/lib/browser/mini-browser-open-handler';
import { ApplicationShell } from '@theia/core/lib/browser';
import { MessageService } from '@theia/core';
import { WindowService } from '@theia/core/lib/browser/window/window-service';
import { Status } from "../Status";
import { LoggerManager } from '../../managers/logger-manager';

/**
 * Link button props.
 * @property {string} title - Button title.
 * @property {React.RefObject<HTMLButtonElement>} internalRef - React reference to the "open internally" button. Created
 * by the parent module and passed to the child.
 * @property {React.RefObject<HTMLButtonElement>} externalRef - React reference to the "open externally" button. Created
 * by the parent module and passed to the child.
 * @property  {string | undefined} url - URL to open.
 * @property {Status} status - Affects if the button is hidden or loading.
 * @property {ApplicationShell} appShell
 * @property {VariableResolverService} varResolver
 * @property {MiniBrowserOpenHandler} miniBrowserHandler
 * @property {MessageService} messageService
 * @property {WindowService} windowService
 */
export interface LinkButtonProps {
  title: string;
  internalRef: React.RefObject<HTMLButtonElement>;
  externalRef: React.RefObject<HTMLButtonElement>;
  appShell: ApplicationShell;
  varResolver: VariableResolverService;
  miniBrowserHandler: MiniBrowserOpenHandler;
  messageService: MessageService;
  windowService: WindowService;
  url?: string;
  status: Status;
}

export class LinkButton extends React.Component<LinkButtonProps> {

  protected accessErrorMessage: string = "There was an error opening this link.";
  private isDisabled: boolean;

  render(): React.ReactNode {
    this.isDisabled = (this.props.status != Status.ACTIVE) ? true : false;

    if (this.props.status === Status.STARTING || this.props.status === Status.RESTORING) { // if lazy loading
      return <div className="link-button-container">
        <button ref={this.props.internalRef} className='theia-button primary loading'>{this.props.title}</button>
        <button ref={this.props.externalRef} className='theia-button primary external-link loading'>
          <span className="external-link-icon" style={{ backgroundColor: "transparent" }}></span>
        </button>
      </div>
    } else {
      return <div className="link-button-container" style={{ display: 'flex' }}>
        <button ref={this.props.internalRef} className='theia-button primary' title='Open here'
          onClick={async (_a) => this.openPreview(false, this.props.url)}>{this.props.title}</button>
        <button ref={this.props.externalRef} className='theia-button primary external-link' title='Open in new browser tab'
          onClick={async (_a) => this.openPreview(true, this.props.url)}>
          <span className="external-link-icon"></span>
        </button>
      </div>
    }
  }

  /**
   * Open a URL (similar to Preview: Open URL command from command palette, except we've duplicated the logic and customized it).
   * @param title - Browser tab title.
   * @param URL - Desired URL to be opened.
   * @param externally - If true, a URL will opened in a separate browser's tab. Otherwise, into an embedded mini-browser.
   */
  protected async openPreview(externally: boolean, url?: string): Promise<void> {
    if (this.isDisabled || this.props.internalRef.current?.disabled || url === undefined) {
      this.props.messageService.error(this.accessErrorMessage);
    } else {
      try {
        if (externally) {
          await HelperService.previewExternally(url, this.props.varResolver, this.props.windowService);
        } else {
          await HelperService.previewInternally(url, this.props.title as string, this.props.varResolver,
            this.props.miniBrowserHandler, this.props.appShell, this.props.messageService);
        }
      } catch (e) {
        this.props.messageService.error(this.accessErrorMessage);
        LoggerManager.getInstance()?.error(e);
      }
    }
  }

}
