import React = require('react');
import { TheiaServices } from '../../../tab-page-widget';
import { Status } from "../../../Status";
import { CopyText } from '../../copy-text';
import { ApplicationInfo } from '../../../database-tab';

/**
 * Export a function called render to be used by default in the Connection Information ApplicationTabPanel.
 */
module.exports = {
  render: function (app: ApplicationInfo, theia: TheiaServices, status: Status):
  React.DetailedHTMLProps<React.HTMLAttributes<HTMLParagraphElement>, HTMLParagraphElement> {

    // Define the panel prompt depending on status and application category.
    let prompt: string;
    if (Status.showTabPanelContent(status)) {
      prompt = ""
    } else {
      prompt = "Press Start to retrieve this information."
    }

    // For each piece of info in the app's connection information, create a copy container.
    let copyContainers: JSX.Element[] = [];
    if ((Status.showTabPanelContent(status)) && app.connectionInformation) {
      Object.entries(app.connectionInformation).forEach((entry: any) => {
        copyContainers.push(
          <CopyText key={entry[0]} status={status} label={entry[0]} value={entry[1]} applicationId={app.id}
            messageService={theia.messageService} />
        );
      });
      if (Object.entries(app.connectionInformation).length == 0) {
        copyContainers.push(
          <CopyText key={0} status={status} 
            label={`There has been an error fetching connection information`} 
            value={`Your service is still up, if you would like to request new credentials please stop and start the service again.`} 
            applicationId={app.id}
            messageService={theia.messageService} />
        );
      }
    }

    // Render everything
    return <div>
      <p>{prompt}</p>
      <div className="generated-info-container">
        {copyContainers}
      </div>
    </div>

  }
}
