import { MessageService } from "@theia/core";
import {ApplicationShell, OpenerService, open} from "@theia/core/lib/browser";
import { BackendService } from "../../common/my-service-protocol";
import URI from "@theia/core/lib/common/uri";
import {LoggerManager} from "./logger-manager";
import {TerminalService} from "@theia/terminal/lib/browser/base/terminal-service";
import {ThemeService} from "@theia/core/lib/browser/theming";
import {HelperService} from "../helper-service";
import { VariableResolverService } from '@theia/variable-resolver/lib/browser';
import {MiniBrowserOpenHandler} from "@theia/mini-browser/lib/browser/mini-browser-open-handler";
import {WindowService} from "@theia/core/lib/browser/window/window-service";
import { FileService } from "@theia/filesystem/lib/browser/file-service";

import * as config from "../../common/config.json";
import { SkillsNetworkWidget } from "../skills-network-widget";

/** Theia services necessary to instantiate EventListenerManager. */
export interface ManagerServices {
  backend: BackendService;
  messaging: MessageService;
  openerService: OpenerService;
  terminalService: TerminalService;
  themeService: ThemeService;
  varResolver: VariableResolverService;
  miniBrowserHandler: MiniBrowserOpenHandler;
  appShell: ApplicationShell;
  windowService: WindowService;
  fileService : FileService;
  skillsNetworkWidget: SkillsNetworkWidget;
}


export class EventListenerManager {
  private static _instance: EventListenerManager;

  protected parentURL: string;

  // SERVICES
  protected backendService: BackendService;
  protected messageService: MessageService;
  protected openerService: OpenerService;
  protected terminalService: TerminalService;
  protected themeService: ThemeService;
  protected varResolver: VariableResolverService;
  protected miniBrowserHandler: MiniBrowserOpenHandler;
  protected appShell: ApplicationShell;
  protected windowService: WindowService;
  protected fileService: FileService;

  protected skillsNetworkWidget: SkillsNetworkWidget;

  // SINGLETON CONSTRUCTOR AND GETTER
  private constructor(services: ManagerServices) {
    this.backendService = services.backend;
    this.messageService = services.messaging;
    this.openerService = services.openerService;
    this.terminalService = services.terminalService;
    this.themeService = services.themeService;
    this.varResolver = services.varResolver;
    this.miniBrowserHandler = services.miniBrowserHandler;
    this.appShell = services.appShell;
    this.windowService = services.windowService;
    this.fileService = services.fileService;
    this.skillsNetworkWidget = services.skillsNetworkWidget;
  }

  public static initializeListeners(services: ManagerServices) {
    if (!this._instance) {
      this._instance = new EventListenerManager(services);
      console.log("starting listeners (Theia)")

      this._instance.startListeners()
      .then( () => {
        //send request to praent UI to inidicate that theia is loaded and ready
      this._instance.requestToUI({type: "frame_loaded"})
      });
    }
    return this._instance;
  }

  public static getEventListeners(){
    return this._instance;
  }

  public requestToUI(data: { [key: string]: any }) {
    if (this.parentURL){
      LoggerManager.getInstance({backend: this.backendService})?.info(`sending message to parent`)
      console.log("Sending request to UI (Theia)");
      parent.postMessage(data, this.parentURL)
      LoggerManager.getInstance({backend: this.backendService})?.info("message to parent sent")
    }
  }

  public async startListeners(){

    // confirmation window to make sure that users are aware of the potential loss of changes
    window.addEventListener('click', warnAboutLostChanges);
    function warnAboutLostChanges() {
      window.addEventListener('beforeunload', function(e) { e.preventDefault(); })
      window.removeEventListener('click', warnAboutLostChanges);
    }

    if (window.location == window.parent.location) {
      this.parentURL = ""
      return
    }

    if (config.development.isDevelopment){
      this.parentURL = "http://monocle.localhost:5000"
    }
    else{
      const staging = await this.backendService.isStaging() ? "staging." : "";
      this.parentURL = `https://labs.${staging}cognitiveclass.ai`;
    }

    console.log("Adding event listener THEIA");
    window.addEventListener("message", (event) => {
      if (config.development.isDevelopment == false && event.origin != this.parentURL) return;
      if (event && event.data) {
        const type = event.data.type;
        switch (type) {
          case "create_directory":
            this.createDirectory(event.data.path)
            break
          case "execute_code":
            this.executeCode(event.data.command)
            break
          case "update_theme":
            this.updateTheme(event.data.color)
            break
          case "launch_application":
            //{type: "launch_application", port: port, viewType: viewType, route: route}
            this.launchApplication(event.data.port, event.data.viewType, event.data.route)
            break
          case "open_file":
            this.openFile(event.data.uri);
            break
          case "open_db_page":
            this.openApplication(event.data.db, event.data.start, "database")
            break
          case "open_big_data_page":
            this.openApplication(event.data.tool, event.data.start, "bigData")
            break
          case "open_cloud_page":
            console.log('In open_cloud_page')
            console.log(event.data);
            this.openApplicationV2(event.data.tool, event.data.action, "cloud")
            break
          case "open_embeddable_ai_page":
            console.log('In open_embeddable_ai_page')
            console.log(event.data);
            this.openApplicationV2(event.data.tool, event.data.action, "embeddableAI")
            break
        }
      }
    })
   
  }

  async getParentURL() {
    if (this.parentURL){
      return new Promise<any>(async (resolve, reject) => {
        this.timeoutMax().catch(e => reject(e))
        LoggerManager.getInstance({backend: this.backendService})?.info(`sending message to parent`)
        this.requestToUI({type: "current_ui_url"})
        LoggerManager.getInstance({backend: this.backendService})?.info("message to parent sent")
        let listener = (event : MessageEvent<any>) => {
          if (config.development.isDevelopment == false && event.origin != this.parentURL) return;
          if (event && event.data && event.data.type == "current_ui_url") {
            resolve(event.data.URL)
            window.removeEventListener("message", listener);
          }
        }
        window.addEventListener("message", listener);
      })
    }
    return Promise.reject("there is no parent")
  }

  sleep(ms: number) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  async timeoutMax() {
    return new Promise(async (resolve, reject) => {
      await this.sleep(5000);
      reject("timeout")
    })
  }

  public async openApplication(db: string, start: string, type: string) {
    let id: string = "";
    for (let i = 0; i < this.skillsNetworkWidget.applications[type].length; i++) {
      if (this.skillsNetworkWidget.applications[type][i].name == db){
         id = this.skillsNetworkWidget.applications[type][i].id
         break;
      }
    }
    if (id) {
      await this.skillsNetworkWidget.openApplicationTab(id, type)
      let startButton = document.getElementById("start-stop-button"+id)
      if (startButton && startButton.innerText == "Start" && start == 'true') startButton.click()
    }
  }

  public async openApplicationV2(tool: string, action: string, type: string) {
    console.log(`Enter openApplicationV2: ${tool}, ${action}, ${type}`);

    if (type === "embeddableAI") {
      for (let app of this.skillsNetworkWidget.embeddableAIComponents) {
        if (app.name === tool) {
          await this.skillsNetworkWidget.openEmbeddableAITab(app.id);
          return;
        }
      }
      console.warn("Could not find embeddable AI component: " + tool);
      return;
    }

    let id: string = "";
    for (let i = 0; i < this.skillsNetworkWidget.applications[type].length; i++) {
      if (this.skillsNetworkWidget.applications[type][i].name == tool){
         id = this.skillsNetworkWidget.applications[type][i].id
         break;
      }
    }
    if (id) {
      console.log(`Has ID: ${id}`);
      await this.skillsNetworkWidget.openApplicationTab(id, type)
      let button = document.getElementById("start-stop-button"+id)
      if (button && button.classList.contains('action-'+action)) button.click()
    }
  }

  public async openFile(path: string) {
    try{
      const uri = new URI(path)
      const exists = await this.fileService.exists(uri)
      if (exists){
          open(this.openerService,uri)
          .catch(e => this.messageService.error("Error: " + e.message))
      }
      else{
        const escapedPath = path.replace(/\_/g,"\\\_");
        this.messageService.info(`${escapedPath} has been created.`);
        await this.fileService.create(uri);
        open(this.openerService,uri)
        .catch( e => this.messageService.error("Error: " + e.message));
      }
    }
    catch(e){
      this.messageService.error("Error: " + e.message)
    }
  }

  public createDirectory(path: string) {
    this.backendService.createDirectory(path)
  }

  public async executeCode(command: string) {
    let term = this.terminalService.lastUsedTerminal
    if (!term) {
      term = await this.terminalService.newTerminal({})
      await term.start()
    }
    this.terminalService.open(term)
    term.sendText(command)
    term.sendText('\n');
  }

  public async updateTheme(color: string) {
    if (color == 'dark') {
      this.themeService.setCurrentTheme('dark')
    } else {
      this.themeService.setCurrentTheme('light')
    }
  }

  public async launchApplication(port: string, viewType: string, route: string) {
    this.messageService.info("Opening your application, this might take a couple seconds.")
    let url = await this.backendService.getLaunchApplicationURL(port);
    if (route.length > 1) {
      url += route
    }
    if (viewType === "internal") {
      HelperService.previewInternally(
        url,
        "application",
        this.varResolver,
        this.miniBrowserHandler,
        this.appShell,
        this.messageService
      )
    } else {
        HelperService.previewExternally(url, this.varResolver, this.windowService)
    }
  }
}
