import React = require('react');
import { TheiaServices } from '../../../tab-page-widget';
import { Status } from "../../../Status";
import { CopyText } from '../../copy-text';
import { ApplicationInfo } from '../../../database-tab';

/**
 * Export a function called render to be used by default in the Connection Information ApplicationTabPanel.
 */
module.exports = {
  render: function (app: ApplicationInfo, theia: TheiaServices, status: Status):
  React.DetailedHTMLProps<React.HTMLAttributes<HTMLParagraphElement>, HTMLParagraphElement> {

    // Define the panel prompt depending on status and application category.
    let prompt: string;
    let exampleHeader: any;
    if (Status.showTabPanelContent(status)) {
      prompt = ""
      exampleHeader = <h2>Example Commands:</h2>
    } else {
      prompt = "Press the button above to prepare your Code Engine Project and view this information."
      exampleHeader = ""
    }

    let projectValue = "Code Engine - ${SN_ICR_NAMESPACE}";
    let namespaceValue = "us.icr.io/${SN_ICR_NAMESPACE}";
    if ((Status.showTabPanelContent(status)) && app.connectionInformation) {
      projectValue = app.connectionInformation["Project"];
      namespaceValue = app.connectionInformation["ICR Namespace"];
    }

    // Render everything
    return <div>
      <p>{prompt}</p>
      <div className="generated-info-container">
        <CopyText key="Project Name" status={status} label="Project Name" value={projectValue} applicationId={app.id}
          messageService={theia.messageService} />

        <CopyText key="Registry Secret" status={status} label="Registry Secret" value="icr-secret" applicationId={app.id}
          messageService={theia.messageService} />

        <CopyText key="ICR Namespace" status={status} label="ICR Namespace" value={namespaceValue} applicationId={app.id}
          messageService={theia.messageService} />

        {exampleHeader}

        <div className="example-commands">
          <CopyText key="Code Engine CLI Command" status={status} label="Code Engine CLI Command" value="ibmcloud ce" applicationId={app.id}
            messageService={theia.messageService} />

          <CopyText key="Current Project Info" status={status} label="Current Project Info" value="ibmcloud ce project current" applicationId={app.id}
            messageService={theia.messageService} />

          <CopyText key="Create Sample Hello World Application" status={status} label="Create Sample Hello World Application" value="ibmcloud ce application create --name myapp --image icr.io/codeengine/hello" applicationId={app.id}
            messageService={theia.messageService} />

          <CopyText key="Create Sample Hello World Application from Source" status={status} label="Create Sample Hello World Application from Source" value="ibmcloud ce application create --name myapp --build-source https://github.com/IBM/CodeEngine --build-context-dir helloworld --image us.icr.io/${SN_ICR_NAMESPACE}/helloworld --registry-secret icr-secret" applicationId={app.id}
            messageService={theia.messageService} />

          <CopyText key="Create Custom Application from Your Image" status={status} label="Create Application from Your Image" value="ibmcloud ce application create --name myapp --image us.icr.io/${SN_ICR_NAMESPACE}/yourimage:tag --registry-secret icr-secret" applicationId={app.id}
            messageService={theia.messageService} />
        </div>

      </div>
    </div>

  }
}
