import { TabPageWidget } from "./tab-page-widget";
import * as React from "react";
import { createTheme, TextField, ThemeProvider } from "@material-ui/core";
import { AlertMessage } from "@theia/core/lib/browser/widgets/alert-message";
import { LoggerManager } from "../managers/logger-manager";
import { HelperService } from "../helper-service";
import { Message } from "@theia/core/lib/browser";


export class OpenLinkTab extends TabPageWidget {

  static readonly childID = 'open-link-tab:widget';

  url: string;
  internalButtonRef: React.RefObject<HTMLButtonElement>;

  constructor() {
    super();
    LoggerManager.getInstance({backend: this.backendService})?.info("OpenLinkTab is being constructed");
    this.internalButtonRef = HelperService.setRef();
  }

  /**
   * Overrides abstract render() method in TabPageWidget.
   */
  protected render(): React.ReactNode {
    return (<div id='tab-container-with-padding'>
      <div className="title-container">
        <h1>Open Link inside IDE</h1>
      </div>
      <hr />
      <AlertMessage type='INFO' header="Navigate to a link right here inside the Cloud IDE, allowing for easy viewing
        alongside your project or course instructions." />
      <AlertMessage type='WARNING' header="Due to how web security policies interact with iframes, certain links cannot be viewed with this feature." />
      <form name="linkForm" onSubmit={async (e) => {
        e.preventDefault();
        // Close this tab.
        this.appShell.closeWidget(this.id);
        // Give focus to recently opened mini browser or last active tab in main area.
        this.appShell.activatePreviousTabInTabBar(this.appShell.getTabBarFor("main"));
      }}>
        <ThemeProvider theme={this.theme}>
          <TextField
            id="standard-basic"
            label="Link"
            style={{
              width: '100%',
              color: "blue",
              textAlign: "center",
              marginTop: '8px',
              marginBottom: '20px',
              padding: "8px 8px 8px 0"
            }}
            onChange={async (e) => this.handleChange(e.target.value)}
            InputLabelProps={{ style: { color: 'var(--theia-foreground)', fontSize: '13px' } }}
            InputProps={{ style: { color: 'var(--theia-foreground)', marginTop: '8px' } }}
          />
        </ThemeProvider>
        <div className="button-container">
          <button ref={this.internalButtonRef} className='theia-button primary' title='Open inside IDE'
            style={{marginLeft: 0}} onClick={async (_a) => this.openLinkInsideIDE(this.url)}>Open</button>
        </div>
      </form>
    </div>)
  }

  protected async handleChange(value: string) {
    // Set url to inputted value.
    this.url = value;
    // Enable or disable Open button based on empty input or not.
    const internalButton = this.internalButtonRef.current;
    if (value && internalButton) {
      internalButton.disabled = false;
    } else if (internalButton) {
      internalButton.disabled = true;
    } else {
      LoggerManager.getInstance({backend: this.backendService})?.info("LinkButton button ref was undefined");
    }
  }

  protected async openLinkInsideIDE(value: string) {
    try {
      await HelperService.previewInternally(value, "Preview", this.varResolver, this.miniBrowserHandler, this.appShell,
        this.messageService);
    } catch (e) {
        this.messageService.error("There was an error opening this link.");
        LoggerManager.getInstance()?.error(e);
    }
  }

  onFirstActivateRequest(): void {
    super.onFirstActivateRequest();
    this.disableLinkButton();
  }

  onAfterAttach(msg: Message): void {
    super.onAfterAttach(msg);
    this.disableLinkButton();
  }

  private disableLinkButton(): void {
    const internalButton = this.internalButtonRef.current;
    if (internalButton) {
      internalButton.disabled = true;
    } else {
      LoggerManager.getInstance({backend: this.backendService})?.info("LinkButton button ref was undefined");
    }
  }

  readonly theme = createTheme({
    overrides: {
      MuiPaper: {
        root: {
          color: 'var(--theia-sideBarSectionHeader-foreground)',
          backgroundColor: 'var(--theia-sideBar-background)'
        }
      }
    }
  })

}
