import React = require('react');
import { TheiaServices } from '../tab-page-widget';
import { Status } from "../Status";
import { ApplicationInfo } from '../database-tab';

/**
 * Tab panel props.
 * @property {string} panelHeading - Title of panel heading within tabbed navigation.
 * @property {ApplicationInfo} applicationInfo - Interface containing all info on the application.
 * @property {TheiaServices} theiaServices - Interface of important Theia Services that are sometimes utilized by components.
 * @property {Status} status - Application status.
 */
export interface TabPanelProps {
  panelHeading: string,
  applicationInfo: ApplicationInfo,
  theiaServices: TheiaServices,
  status: Status
}

export class ApplicationTabPanel extends React.Component<TabPanelProps> {

  /** Render a default or custom template for a tab panel. */
  render(): React.ReactNode {
    let template;
    try {
      template = require('./templates/' + (this.props.applicationInfo.id as string).toLowerCase() + '/' +
        this.props.panelHeading.toLowerCase() + '.js');
    } catch {
      template = require('./templates/defaults/' + this.props.panelHeading.toLowerCase() + '.js');
    }
    // Depending on the panel, the render function may have different parameters.
    // Panel types should have a standardized amount of parameters and parameter types.
    if (this.props.panelHeading === "details") {
      return template.render();
    } else {
      return template.render(this.props.applicationInfo, this.props.theiaServices, this.props.status);
    }
  }

}
