import {ContainerModule} from 'inversify';
import { SkillsNetworkWidget } from './skills-network-widget';
import { SkillsNetworkContribution, BackendCommandContribution } from './skills-network-contribution';
import { bindViewContribution, FrontendApplicationContribution,
  WebSocketConnectionProvider, WidgetFactory } from '@theia/core/lib/browser';

import '../../src/browser/style/index.css';
import { CommandContribution } from "@theia/core";
import { bindTabPageModule } from './tab-page/tab-page-frontend-module';
import { BACKEND_PATH, BackendService } from "../common/my-service-protocol";
import { AboutDialogProps, AboutExtensionDialog } from './components/about-extension-dialog';
import { TabBarToolbarContribution } from '@theia/core/lib/browser/shell/tab-bar-toolbar';
import { SecurityWarningDialog, SecurityWarningProps } from './components/security-warning-dialog';

/** Register contributions (new features) to theia context (theia core extension) to integrate this new extension
 * into the overall IDE. */
export default new ContainerModule(bind => {
  // register new widget (literally sidebar button)
  bindViewContribution(bind, SkillsNetworkContribution);
  bind(FrontendApplicationContribution).toService(SkillsNetworkContribution);
  bind(SkillsNetworkWidget).toSelf();
  bind(WidgetFactory).toDynamicValue(ctx => ({
    id: SkillsNetworkWidget.ID,
    createWidget: () => ctx.container.get<SkillsNetworkWidget>(SkillsNetworkWidget)
  })).inSingletonScope();

  // bind dialog panes
  bind(AboutExtensionDialog).toSelf().inSingletonScope();
  bind(AboutDialogProps).toConstantValue({ title: 'About' });
  bind(SecurityWarningDialog).toSelf().inSingletonScope();
  bind(SecurityWarningProps).toConstantValue({ title: 'Warning' });

  // bind widget toolbar (sidebar top right menu)
  bind(TabBarToolbarContribution).toService(SkillsNetworkContribution);

  // bind tab pages
  bindTabPageModule(bind);

  // bind the backend
  bind(CommandContribution).to(BackendCommandContribution).inSingletonScope();
  bind(BackendService).toDynamicValue(ctx => {
    const connection = ctx.container.get(WebSocketConnectionProvider);
    return connection.createProxy<BackendService>(BACKEND_PATH);
  }).inSingletonScope();

});
