import { injectable, inject } from 'inversify';
import { MenuModelRegistry } from '@theia/core';
import { AbstractViewContribution } from '@theia/core/lib/browser';
import { Command, CommandRegistry } from '@theia/core/lib/common/command';
import { WorkspaceService } from '@theia/workspace/lib/browser';
import { FrontendApplicationStateService } from '@theia/core/lib/browser/frontend-application-state';
import { TabPageWidget } from './tab-page-widget';

export const TabPageCommand: Command = { id: 'tab-page:command' };

@injectable()
export class TabPageContribution extends AbstractViewContribution<TabPageWidget> {

    @inject(FrontendApplicationStateService)
    protected readonly stateService: FrontendApplicationStateService;

    @inject(WorkspaceService)
    protected readonly workspaceService: WorkspaceService;

    /**
     * `AbstractViewContribution` handles the creation and registering
     *  of the widget including commands, menus, and keybindings.
     *
     * We can pass `defaultWidgetOptions` which define widget properties such as
     * its location `area` (`main`, `left`, `right`, `bottom`), `mode`, and `ref`.
     *
     */
    constructor() {
        super({
            widgetId: TabPageWidget.ID,
            widgetName: TabPageWidget.LABEL,
            defaultWidgetOptions: { area: 'main'},
            toggleCommandId: TabPageCommand.id
        });
    }

    /**
     * Example command registration to open the widget from the menu, and quick-open.
     * For a simpler use case, it is possible to simply call:
     ```ts
        super.registerCommands(commands)
     ```
     *
     * For more flexibility, we can pass `OpenViewArguments` which define
     * options on how to handle opening the widget:
     *
     ```ts
        toggle?: boolean
        activate?: boolean;
        reveal?: boolean;
     ```
     *
     * @param commands
     */

    registerCommands(commands: CommandRegistry): void {
        commands.registerCommand(TabPageCommand, {
            execute: () => super.openView({ activate: true, reveal: true, toggle: true })
        });
    }

    /**
     * Example menu registration to contribute a menu item used to open the widget.
     * Default location when extending the `AbstractViewContribution` is the `View` main-menu item.
     * Empty because we only open tabs from the Skills Network sidebar widget.
     * @param _menus
     */
    registerMenus(_menus: MenuModelRegistry): void {}
}
