import { injectable, inject } from 'inversify';
import {CommandContribution, MenuModelRegistry} from '@theia/core';
import { SkillsNetworkWidget } from './skills-network-widget';
import { AbstractViewContribution, FrontendApplication, Widget } from '@theia/core/lib/browser';
import { Command, CommandRegistry } from '@theia/core/lib/common/command';
import { WorkspaceService } from '@theia/workspace/lib/browser';
import { FrontendApplicationStateService } from '@theia/core/lib/browser/frontend-application-state';
import { AboutExtensionDialog } from './components/about-extension-dialog';
import { TabBarToolbarContribution, TabBarToolbarRegistry } from '@theia/core/lib/browser/shell/tab-bar-toolbar';
import { SecurityWarningDialog } from './components/security-warning-dialog';

export const SkillsNetworkCommand: Command = {
  id: 'skills-network:command'
};
export const ABOUT_EXTENSION: Command = {
  id: 'about-extension.toolbarCommand',
  iconClass: 'codicon codicon-question'
}
export const COLLAPSE_ALL: Command = {
  id: 'collapse-all.toolbarCommand',
  iconClass: 'codicon codicon-collapse-all'
}
export const SECURITY_WARNING: Command = {
  id: 'security-warning:command'
}

@injectable()
export class SkillsNetworkContribution extends AbstractViewContribution<SkillsNetworkWidget> implements TabBarToolbarContribution {

    @inject(FrontendApplicationStateService)
    protected readonly stateService: FrontendApplicationStateService;

    @inject(WorkspaceService)
    protected readonly workspaceService: WorkspaceService;

    @inject(AboutExtensionDialog)
    protected readonly aboutExtensionDialog: AboutExtensionDialog

    @inject(SecurityWarningDialog)
    protected readonly securityWarningDialog: SecurityWarningDialog

    /**
     * `AbstractViewContribution` handles the creation and registering
     *  of the widget including commands, menus, and keybindings.
     *
     * We can pass `defaultWidgetOptions` which define widget properties such as
     * its location `area` (`main`, `left`, `right`, `bottom`), `mode`, and `ref`.
     *
     */
    constructor() {
        super({
            widgetId: SkillsNetworkWidget.ID,
            widgetName: SkillsNetworkWidget.LABEL,
            defaultWidgetOptions: { area: 'left'},
            toggleCommandId: SkillsNetworkCommand.id
        });
    }

    /**
     * Example command registration to open the widget from the menu, and quick-open.
     * For a simpler use case, it is possible to simply call:
     ```ts
        super.registerCommands(commands)
     ```
     *
     * For more flexibility, we can pass `OpenViewArguments` which define
     * options on how to handle opening the widget:
     *
     ```ts
        toggle?: boolean
        activate?: boolean;
        reveal?: boolean;
     ```
     *
     * @param commands
     */

    // initializeLayout adds view as part of default layout
    async initializeLayout(app: FrontendApplication): Promise<void> {
        await this.openView({ activate: false });
    }

    // onStart opens view when application is started
    async onStart(app: FrontendApplication): Promise<void> {
        if (!this.workspaceService.opened) {
            this.stateService.reachedState('ready').then(
                () => this.openView({ reveal: true })
            );
        }
    }

    registerCommands(commands: CommandRegistry): void {
        commands.registerCommand(SkillsNetworkCommand, {
            execute: () => super.openView({ activate: false, reveal: true, toggle: true })
        });

        commands.registerCommand(ABOUT_EXTENSION, {
            execute: () => this.openAboutExtension(),
            isEnabled: widget => this.withWidget(widget, () => true),
            isVisible: widget => this.withWidget(widget, () => true)
        });

        commands.registerCommand(COLLAPSE_ALL, {
            execute: () => this.collapseAll(),
            isEnabled: widget => this.withWidget(widget, () => true),
            isVisible: widget => this.withWidget(widget, () => true)
        });

        commands.registerCommand(SECURITY_WARNING, {
            execute: (env: string) => this.openSecurityWarning(env)
        });
    }

    protected withWidget<T>(widget: Widget | undefined = this.tryGetWidget(), cb: (sampleView: SkillsNetworkWidget) => T): T | false {
      if (widget instanceof SkillsNetworkWidget && widget.id === SkillsNetworkWidget.ID) {
          return cb(widget);
      }
      return false;
    }

    /**
     * Example menu registration to contribute a menu item used to open the widget.
     * Default location when extending the `AbstractViewContribution` is the `View` main-menu item.
     *
     * We can however define new menu path locations in the following way:
     ```ts
        menus.registerMenuAction(CommonMenus.HELP, {
            commandId: 'id',
            label: 'label'
        });
     ```
     *
     * @param menus
     */
    registerMenus(menus: MenuModelRegistry): void {
        super.registerMenus(menus);
        // register context menus here
    }

    /** Register commands to the sidebar toolbar. */
    async registerToolbarItems(toolbarRegistry: TabBarToolbarRegistry): Promise<void> {
      toolbarRegistry.registerItem({
        id: COLLAPSE_ALL.id,
        command: COLLAPSE_ALL.id,
        tooltip: 'Collapse all',
        priority: 0
      });
      toolbarRegistry.registerItem({
        id: ABOUT_EXTENSION.id,
        command: ABOUT_EXTENSION.id,
        tooltip: 'About Skills Network Toolbox',
        priority: 1
      });
    }

    /** CUSTOM COMMANDS */
    protected async openAboutExtension(): Promise<void> {
      this.aboutExtensionDialog.open();
    }

    protected async openSecurityWarning(env: string): Promise<void> {
      this.securityWarningDialog.set(env);
    }

    protected async collapseAll(): Promise<void> {
      const sidebar = document.getElementById("widget-container");
      if (sidebar) {
        const dropdowns = sidebar.getElementsByClassName("MuiButtonBase-root MuiAccordionSummary-root Mui-expanded");
        const l = dropdowns.length;
        for (var i = 0; i < l; i++) {
          (dropdowns[0] as HTMLElement).click();
        }
      }
    }

}

const BackendCommand: Command = {
  id: 'skillsNetworkBackend.command',
  label: 'Skills Network extension backend',
};

@injectable()
export class BackendCommandContribution implements CommandContribution {
  constructor() { }
  registerCommands(registry: CommandRegistry): void {
    registry.registerCommand(BackendCommand, {
      execute: () => console.log("backend up")
    });
  }
}
