import * as React from 'react';
import { inject, injectable, postConstruct } from 'inversify';
import { ReactDialog } from '@theia/core/lib/browser/dialogs/react-dialog';
import { DialogProps } from '@theia/core/lib/browser/dialogs';
import { Message } from '@theia/core/lib/browser';
import { Environment } from '../../common/environment';
import { BackendService } from '../../common/my-service-protocol';
import { MessageService } from '@theia/core';
import { HelperService } from '../helper-service';
import { VariableResolverService } from '@theia/variable-resolver/lib/browser';
import { WindowService } from '@theia/core/lib/browser/window/window-service';
import {LoggerManager} from "../managers/logger-manager";
import { EventListenerManager } from '../managers/event-listeners-manager';

@injectable()
export class SecurityWarningProps extends DialogProps {}

/** Pop up dialog that warns the user when switching to an unsecure Cloud IDE environment. */
@injectable()
export class SecurityWarningDialog extends ReactDialog<void> {
  protected readonly okButton: HTMLButtonElement;
  protected env: Environment;
  protected readonly errorMessage: string = "There was an error opening your Cloud IDE in another environment. \
  Please refresh and try again.";

  @inject(BackendService)
  protected readonly backendService: BackendService;

  @inject(MessageService)
  protected readonly messageService: MessageService;

  @inject(VariableResolverService)
  protected readonly varResolver: VariableResolverService;

  @inject(WindowService)
  protected readonly windowService: WindowService;

  constructor(@inject(SecurityWarningProps) protected readonly props: DialogProps) {
    super({ title: "Skills Network Toolbox" });
    const acceptWarning = (_e: MouseEvent) => {
      this.openEnvironment();
      super.close();
    };
    this.appendAcceptButton('Yes').addEventListener("click", acceptWarning);
    this.appendAcceptButton('No');
  }

  @postConstruct()
  protected init(): void {
    this.doInit();   
  }

  protected async doInit(): Promise<void> {
      this.update();
  }

  set(environment: string) {
    this.env = Environment.fromString(environment);
    if (this.env === Environment.THEIA) {
      // Opening regular theia doesn't require a warning
      this.openEnvironment();
    } else {
      super.open();
    }
  }

  protected render(): React.ReactNode {
    return <div style={{maxWidth: '400px'}}>

      <p>Please be aware that the {Environment.toString(this.env)} environment does not protect your private credentials.
      For your safety, please refrain from entering any credentials, secrets, or personal information.</p>
      <p>By switching to a different Cloud IDE environment, you might lose your course or project progress in the new
      tab.</p>
      <p>Would you still like to proceed?</p>

    </div>
  }

  protected async openEnvironment(): Promise<void> {
    try {
      let currentURL: URL;

      try {
        const url = await EventListenerManager.getEventListeners().getParentURL();
        LoggerManager.getInstance({backend: this.backendService})?.info(`received URL from parent window as: ${url}`)
        currentURL = new URL(url);
      } catch (e) {
        LoggerManager.getInstance({backend: this.backendService})?.error(`Getting URL from parent window failed with message: ${e}`)
        currentURL = new URL(document.referrer);
      }

      // Get the instructions URL
      this.backendService.log_info(`got currentURL as ${currentURL}`);
      let instructions = currentURL.searchParams.get("md_instructions_url");

      //If we don't have the theia URL and no instructions, open Labs without any class
      if (!instructions) {
        instructions = "404"
        this.messageService.warn("There was an issue retrieving the current course you " +
          "are working on, we will still open theia but you will not be able to follow along with " +
          "your course.");
      }
      let finalURL: string;

      if (instructions === "404" && document.URL) {
        finalURL = document.URL;
      }  else {
        // See if we are on staging
        const staging = await this.backendService.isStaging() ? "staging." : "";
        // Put together the final URL
        finalURL = `https://labs.${staging}cognitiveclass.ai/tools/${Environment.getPath(this.env)}/?md_instructions_url=${instructions}&lti=true`;
        LoggerManager.getInstance({backend: this.backendService})?.info(`window url: ${currentURL}`);
        LoggerManager.getInstance({backend: this.backendService})?.info(`instruction url: ${instructions}`);
        LoggerManager.getInstance({backend: this.backendService})?.info(`final url: ${finalURL}`);

      }

      if (currentURL.searchParams.get("instruction_mode") && currentURL.searchParams.get("instruction_token")) {
        const instructionMode = currentURL.searchParams.get("instruction_mode");
        const instructionToken = currentURL.searchParams.get("instruction_token");
        finalURL += `&instruction_mode=${instructionMode}&instruction_token=${instructionToken}`
      }

      HelperService.previewExternally(finalURL, this.varResolver, this.windowService);

    } catch (e) {
      this.messageService.error(this.errorMessage);
    }
  }

  protected onAfterAttach(msg: Message): void {
    super.onAfterAttach(msg);
    this.update();
  }

  get value(): undefined { return undefined; }
}
