import React = require('react');
import { HelperService } from '../helper-service';


/**
 * SidebarIconButton props.
 */
export interface SidebarIconButtonProps {
  id: string;
  hide: boolean;
  description: string;
  label: string;
  icon: string;
  onClick: React.MouseEventHandler<HTMLDivElement>;
}

export class SidebarIconButton extends React.Component<SidebarIconButtonProps> {

  render(): React.ReactNode {
    if (!this.props.hide) {
      return <div onClick={() => HelperService.handleButtonFocus(this.props.id)}>

        <div className="theia-TreeNode skills-network" id={this.props.id} title={this.props.description}
        onClick={this.props.onClick}>
          <div className="theia-TreeNodeContent">
            <div className="noWrapInfo">
              <span className={`sidebar-icon ${this.props.icon}`}></span>
              <span className="app-description">{this.props.label}</span>
            </div>
          </div>
        </div>

      </div>
    } else {
      return null
    }
  }

}
