import * as React from 'react';
import { inject, injectable, postConstruct } from 'inversify';
import { ReactDialog } from '@theia/core/lib/browser/dialogs/react-dialog';
import { DialogProps } from '@theia/core/lib/browser/dialogs';
import { ApplicationServer, ExtensionInfo } from '@theia/core/lib/common/application-protocol';
import { Message } from '@theia/core/lib/browser';

const SMALLER_TEXT = 'about-extension';
export const FEEDBACK_LINK: string = "https://support.labs.cognitiveclass.ai/clients/widgets/classic_widget?contact_enabled=true&default_mode=support&embed_type=lightbox&feedback_enabled=true&link_color=007dbf&magic_auth_enabled=true&mode=full&primary_color=19496A&referrer=https%3A%2F%2Flabs.cognitiveclass.ai%2Ftools%2Ftheiadocker%2F%3Fmd_instructions_url%3Dhttps%3A%2F%2Fcf-courses-data.s3.us.cloud-object-storage.appdomain.cloud%2Fcc201%2Flabs%2F5_FinalProject_Coursera%2Finstructions.md%26lti%3Dtrue&strings=e30%3D&trigger_background_color=19496A&trigger_method=pin#create_idea";

@injectable()
export class AboutDialogProps extends DialogProps {}

/** Pop up dialog for "About Skills Network Toolbox". */
@injectable()
export class AboutExtensionDialog extends ReactDialog<void> {
  protected extensionsInfos: ExtensionInfo[] = [];
  protected readonly okButton: HTMLButtonElement;

  @inject(ApplicationServer)
  protected readonly appServer: ApplicationServer;

  constructor(@inject(AboutDialogProps) protected readonly props: AboutDialogProps) {
    super({ title: "Skills Network Toolbox" });
    this.appendAcceptButton('Ok');
  }

  @postConstruct()
  protected init(): void {
    this.doInit();   
  }

  protected async doInit(): Promise<void> {
      this.extensionsInfos = await this.appServer.getExtensionsInfos();
      this.update();
  }

  protected getExtensionVersion(): React.ReactNode {
    const extension = this.extensionsInfos.find(extension => extension.name === "skills-network-extension");
    if (extension) {
      return <p className={SMALLER_TEXT}>Version {extension.version}</p>
    } else {
      return null
    }
  }

  protected getFeatures(): (JSX.Element | undefined)[] {
    const sidebarButtons = document.getElementsByClassName("theia-TreeNode skills-network");
    // Get button description and turn it into a bullet point
    const features: (JSX.Element | undefined)[] = Array.from(sidebarButtons).map((button: Element) => {
      let description = button.getAttribute('title');
      if (description && (description.indexOf("Coming soon") < 0)) {
        // remove trailing period
        description = description.replace(/\.$/, "");
        return <li key={button.id}>{description}</li>
      }
    })
    // Check that features are not all undefined
    .filter(feature => feature !== undefined);
    if (features.length > 0) {
      return features
    } else {
      return [<i key="loading">Loading...</i>]
    }
  }

  protected render(): React.ReactNode {
    return <div style={{maxWidth: '600px', display: 'flex'}}>

      {/* LEFT COLUMN */}
      <div className="about-extension-column left">
        <div id="about-skills-network-logo"></div>
        {this.getExtensionVersion()}
        <p className={SMALLER_TEXT}><a href="https://skills-network-labs.noticeable.news/posts/sn-labs-june-25-2021-enhancements" target="_blank" rel="noopener noreferrer">
          What's new?
        </a></p>
        <p className={SMALLER_TEXT}><a href={FEEDBACK_LINK} target="_blank" rel="noopener noreferrer">Suggest a feature or submit feedback</a></p>
      </div>

      {/* RIGHT COLUMN */}
      <div className="about-extension-column right">
        <p style={{marginTop: '0'}}>The Skills Network Toolbox helps you efficiently and easily interact with a number of technologies inside the
          Skills Network Cloud IDE. From databases to cloud platforms, learn to navigate the latest and greatest
          technologies alongside your course or project instructions.</p>
        <p>Current features supported include: </p>
          <ul className='about-features'>
            {this.getFeatures()}
          </ul>
        <p className={SMALLER_TEXT} style={{
          textAlign: 'left',
          margin: '0',
          color: 'var(--theia-secondaryButton-disabledForeground)'}}>
            <i>Developed with love by the Skills Network team.</i>
        </p>
      </div>

    </div>;
  }

  protected onAfterAttach(msg: Message): void {
    super.onAfterAttach(msg);
    this.update();
  }

  get value(): undefined { return undefined; }
}
