import * as React from 'react';
import { MessageService } from "@theia/core";
import { ApplicationShell } from "@theia/core/lib/browser";
import { SidebarAppButton } from "../components/sidebar-app-button";
import { ApplicationInfo, DatabaseTab } from "../tab-page/database-tab";
import { EmbeddableAIComponentInfo } from '../tab-page/embeddable-ai-tab';
import { Status } from "../tab-page/Status";
import { BackendService } from "../../common/my-service-protocol";
import { HelperService } from '../helper-service';
import { VariableResolverService } from '@theia/variable-resolver/lib/browser';
import { WindowService } from '@theia/core/lib/browser/window/window-service';
import {LoggerManager} from "./logger-manager";


function isApplicationInfo(toBeDetermined: ApplicationInfo|EmbeddableAIComponentInfo): toBeDetermined is ApplicationInfo {
  if((toBeDetermined as ApplicationInfo).requiredPorts){
    return true
  }
  return false
}

/** Theia services necessary to instantiate ApplicationManager. */
export interface ManagerServices {
  backend: BackendService;
  shell: ApplicationShell;
  messaging: MessageService;
  varResolver: VariableResolverService;
  window: WindowService;
}

/**
 * Manages applications and their statuses .
 */
export class ApplicationManager {
  private static _instance: ApplicationManager;

  // SERVICES
    protected backendService: BackendService;
    protected appShell: ApplicationShell;
    protected messageService: MessageService;
    protected varResolver: VariableResolverService;
    protected windowService: WindowService;

  // DATA
    protected applications: { [appId: string]: ApplicationInfo|EmbeddableAIComponentInfo };
    protected statuses: { [appId: string]: Status };
    protected sidebarReferences: { [appId: string]: React.RefObject<SidebarAppButton> };

  // SINGLETON CONSTRUCTOR AND GETTER
    private constructor(services: ManagerServices) {
      this.applications = {};
      this.statuses = {};
      this.sidebarReferences = {};
      this.backendService = services.backend;
      this.appShell = services.shell;
      this.messageService = services.messaging;
      this.varResolver = services.varResolver;
      this.windowService = services.window;
    }

    public static getInstance(services: ManagerServices) {
      if (!this._instance) {
          this._instance = new ApplicationManager(services);
        }
      return this._instance;
    }

  // MAIN METHODS

    /** Add an application to the manager.
     * @param {string} id - Application id.
     * @param {React.RefObject<SidebarAppButton>} ref - Sidebar component reference (to change status in sidebar).
    */
    public addApplication(id: string, info: ApplicationInfo|EmbeddableAIComponentInfo, status: Status, ref: React.RefObject<SidebarAppButton>) {
      this.applications[id] = info;
      this.statuses[id] = status;
      this.sidebarReferences[id] = ref;
    }

  public async getActiveApps() {
      const activeApps = [];
      const activeAppsAndPorts: { title: string; value: string; }[] = [];
      for (const [key, value] of Object.entries(this.statuses)) {
        if (value === Status.IDLE) {
          try{
            const isActive = await this.backendService.isApplicationUp(key)
            if (isActive) {
              activeApps.push(key)
            }
          } catch (e) {
            LoggerManager.getInstance()?.error(e)
          }
        }
        if (value === Status.ACTIVE) {
          activeApps.push(key)
        }
      }

      activeApps.forEach(appId => {
        const app = this.applications[appId];
        if (isApplicationInfo(app)  && app["webEnabled"]) {
          const currentValue = app["publicPort"];
          const currentKey = app["name"];
          activeAppsAndPorts.push({ title: `${currentValue} (${currentKey})`, value: `${currentValue}` })
        }
      })

      return activeAppsAndPorts;
    }

    public getStatus(id: string): Status {
      return this.statuses[id]
    }

    public get allStatuses(): { [appId: string]: Status } {
      return this.statuses
    }

    public set allStatuses(stored: { [appId: string]: Status }) {
      this.statuses = stored;
    }

    public includesAppStatus(id: string): boolean {
      return (id in this.statuses)
    }

    public fixStatus(id: string): Status {
      if (this.statuses[id] === Status.DISABLED) {
        this.changeStatus(id, Status.INACTIVE, true);
        return Status.INACTIVE;
      }
      return this.statuses[id];
    }

    /** Change an application status in the tab page and in the sidebar button.
     * @param {string} id - Application id.
     * @param {Status} newStatus - Status to change to.
     */
    protected changeStatus(id: string, newStatus: Status, skipSidebar: boolean = false) {
      // Change tab status (if it's opened)
      if (this.appShell.getWidgetById(id) instanceof DatabaseTab) {
        const tab: DatabaseTab = this.appShell.getWidgetById(id) as DatabaseTab;
        tab.reloadTab(newStatus);
      } else if (newStatus === Status.ACTIVE) {
        // If tab is not opened, but app is ACTIVE, change new state to IDLE
        newStatus = Status.IDLE
      }

      console.log(`Status changed to ${newStatus} for ${id}`);

      this.statuses[id] = newStatus;

      if (!skipSidebar) {
        // Change sidebar status
        const button = this.sidebarReferences[id].current;
        if (button) {
          button.changeStatus(newStatus);
        }
      }
    }

  // START & STOP APP

    public async startApplication(id: string): Promise<void> {
      // Check that port is available first
      let unavailableInternalPorts: { [port: string]: string } = {};
      let unavailableExternalPorts: { [port: string]: string } = {};
      for (const [app, status] of Object.entries(this.statuses)) {
        // If status is loading or active, store the port number
        if (Status.showTabPanelContent(status) || status === Status.IDLE) {

          const theApp = this.applications[app];

          if (isApplicationInfo(theApp)) {
            // Store internal ports
            for (let internal of theApp.requiredPorts[0]) {
              unavailableInternalPorts[internal] = app;
            }
            // Store external ports
            for (let external of theApp.requiredPorts[1]) {
              unavailableExternalPorts[external] = app;
            }
          }
          
        }
      }

      const app = this.applications[id];

      if (!isApplicationInfo(app)) {
        return;
      }

      let busyApp: string | undefined;
      const internalPorts = app.requiredPorts[0];
      const externalPorts = app.requiredPorts[1];
      const ports = internalPorts.concat(externalPorts);
      for (let i = 0; i < ports.length; i++) {
        if (i < internalPorts.length && Object.keys(unavailableInternalPorts).indexOf(ports[i]) > -1) {
          busyApp = this.applications[unavailableInternalPorts[ports[i]]].name;
          break;
        } else if (i >= internalPorts.length && Object.keys(unavailableExternalPorts).indexOf(ports[i]) > -1) {
          busyApp = this.applications[unavailableExternalPorts[ports[i]]].name;
          break;
        }
      }

      // If port is occupied
      if (busyApp) {
        this.throwError(id, `This port is unavailable because ${busyApp} is running on it. Please fully stop ${busyApp} \
        before launching ${app.name}.`);
      }
      // Else start application
      else {
        this.changeStatus(id, Status.STARTING);
        await this.backendService.startApplication(id)
          .then(async (data: { CONNECTION_INFORMATION: any; SUMMARY_CREDENTIALS: any; }) => {
            // Set generated connection info
            this.setPortAndInfo(id, data);
            // Change status to active
            this.changeStatus(id, Status.ACTIVE);
          })
          .catch((e: any) => {
            this.throwError(id, `There was an error starting ${app.name}. Please try again.`, e);
          });
      }
    }

    public async stopApplication(id: string): Promise<void> {
      this.changeStatus(id, Status.STOPPING);
      await this.backendService.stopApplication(id)
        .then(() => {
          this.changeStatus(id, Status.INACTIVE);
        })
        .catch((e: any) => {
          this.throwError(id, `There was an error stopping ${this.applications[id].name}. Please close the tab or try restarting.`, e);
        });
    }

    public async verifyActive(id: string): Promise<void> {
      this.changeStatus(id, Status.RESTORING);
      await this.backendService.isApplicationUp(id)
        .then(async (data: { CONNECTION_INFORMATION: any; SUMMARY_CREDENTIALS: any; }) => {
          // Set generated connection info
          this.setPortAndInfo(id, data);
          // Change status to active
          this.changeStatus(id, Status.ACTIVE);
        })
        .catch(() => {
          this.changeStatus(id, Status.INACTIVE);
          this.messageService.info(`Your previous connection for ${this.applications[id].name} was disposed. Please press Start again to reconnect.`);
        })
    }

  // APPLICATION TAB METHODS

    /** If appropriate, change status when tab is closed. */
    public onCloseTab(id: string, status: Status) {
      if (status === Status.ACTIVE) {
        this.changeStatus(id, Status.IDLE);
      } else if (status === Status.ERROR) {
        this.changeStatus(id, Status.INACTIVE);
      }
    }

    /** Once an application is successfully up, add the port to Launch Application and update the connection information
     * stored in the tab.
     */
    protected setPortAndInfo(id: string, data: { CONNECTION_INFORMATION: any; SUMMARY_CREDENTIALS: any; }) {
      let info = this.applications[id];
      if (!isApplicationInfo(info)) {
        return;
      }
      info = info as ApplicationInfo;
      
      // Add port
      this.backendService.addApplicationPort(info.webAdminName, info.publicPort, info.webEnabled)
        .catch(e => LoggerManager.getInstance()?.error(e));
      // Update connection info stored in tab
      if (this.appShell.getWidgetById(id) instanceof DatabaseTab) {
        const tab: DatabaseTab = this.appShell.getWidgetById(id) as DatabaseTab;
        tab.appInfo = {
          ...info,
          connectionInformation: data.CONNECTION_INFORMATION,
          summaryCredentials: data.SUMMARY_CREDENTIALS
        }
      }
    }

    /** Change an application status to ERROR and display a message for why. */
    protected throwError(id: string, userMessage: string, error?: any) {
      let info = this.applications[id];
      if (isApplicationInfo(info) && info.supportLink) {
         const supportLink = info.supportLink
          this.messageService.error(userMessage, "Support")
            .then(action => action === "Support" && HelperService.previewExternally(supportLink,this.varResolver,
              this.windowService) as void | PromiseLike<void>);
      } else {
        this.messageService.error(userMessage);
      }

      this.changeStatus(id, Status.ERROR);
      LoggerManager.getInstance()?.error(error);
    }
}
