export enum Status {
  INACTIVE,
  STARTING,
  ACTIVE,
  STOPPING,
  ERROR,
  RESTORING,
  IDLE,
  DISABLED
}

export namespace Status {
  export function getColor(status: Status): string {
    switch (status) {
      case Status.INACTIVE:
      case Status.DISABLED:
        return "var(--theia-secondaryButton-disabledForeground)" // grey
      case Status.STARTING:
      case Status.STOPPING:
      case Status.RESTORING:
        return "#3B8DEA" // blue
      case Status.ACTIVE:
        return "#21D08A" // green
      case Status.IDLE:
        return "#298A5D" // darker green
      default:
        return "#F37160" // red
    }
  }

  export function getTitle(status: Status, labels?: { [key: string]: string }): string {
    switch (status) {
      case Status.INACTIVE:
        return labels?.inactive || "inactive"
      case Status.STARTING:
        return labels?.starting || "starting"
      case Status.STOPPING:
        return labels?.stopping || "stopping"
      case Status.ACTIVE:
        return labels?.active || "active"
      case Status.RESTORING:
        return labels?.restoring || "restoring"
      case Status.IDLE:
        return labels?.idle || "idle"
      case Status.DISABLED:
        return labels?.disabled || "disabled"
      default:
        return labels?.error || "error"
    }
  }

  export function showTabPanelContent(status: Status): boolean {
    switch (status) {
      case Status.STARTING:
      case Status.STOPPING:
      case Status.RESTORING:
      case Status.ACTIVE:
        return true
      default:
        return false
    }
  }
}
