import { WindowService } from '@theia/core/lib/browser/window/window-service';
import { VariableResolverService } from '@theia/variable-resolver/lib/browser';
import URI from '@theia/core/lib/common/uri';
import { MiniBrowserOpenHandler } from '@theia/mini-browser/lib/browser/mini-browser-open-handler';
import { ApplicationShell } from '@theia/core/lib/browser';
import { MessageService } from '@theia/core';
import * as React from 'react';
import {LoggerManager} from "./managers/logger-manager";

/**
 * HelperService is a "static" class (as static as it gets since TypeScript doesn't do static classes) that
 * includes common functions shared among widgets.
 */
export class HelperService {

  /**
   * Open the given URL to preview it in a separate browser's tab.
   * Method also tries to resolve the variables in the given URL.
   * @param previewURL - A URL to go to.
   */
  static async previewExternally(previewURL: string, varResolver: VariableResolverService,
    windowService: WindowService): Promise<void> {
    const url = await varResolver.resolve(previewURL);

    if (typeof url === 'string') {
      windowService.openNewWindow(url);
    } else {
      console.error('Invalid URL:', url);
    }
  }

  /**
   * Open the given URL to preview it in the embedded mini-browser.
   * Method also tries to resolve the variables in the given URL.
   * @param previewURL - A URL to preview.
   * @param label - Short description of the given URL. Will be displayed as tab title.
   */
  static async previewInternally(previewURL: string, label: string, varResolver: VariableResolverService,
    miniBrowserHandler: MiniBrowserOpenHandler, appShell: ApplicationShell, messageService: MessageService): Promise<void> {
    const url = await varResolver.resolve(previewURL);
    await miniBrowserHandler.open(new URI(url), {
      iconClass: 'fa fa-window-maximize',
      name: `${label}`,
      toolbar: 'show',
      widgetOptions: {
        area: 'main'
      }
    }).then(() => {
      // close other sidebar panels to maximize mini-browser window
      appShell.collapsePanel("left");
      appShell.collapsePanel("right");
    }).catch((e: any) => {
      LoggerManager.getInstance()?.error(e);
      messageService.error("Unable to open URL in IDE.");
    });
  }

  /**
   * Open a tab panel within TabPageWidgets and give it focus. Make sure that class naming of panels follows
   * convention (panels are named "tab-panel" and headers are named "tab-heading").
   * Ex. See [Summary, Connection Information, Details, ...] in DatabaseTab.
   * @param {string} panelTitle - Tab panel title. Matches the panel element id.
   * @param {string} tabWidgetIdentifier - If there are multiple instances of the same class of Tab widget, use this to
   * distinguish between them (ex. for DatabaseTab, the identifier is the type of database like MySQL or Postgres).
   */
  static openTabPanel(panelTitle: string, tabIdentifier: string) {
    let panel = document.getElementById(panelTitle + tabIdentifier);
    if (panel != null) {
      let i;
      const x = document.getElementsByClassName("tab-panel " + tabIdentifier);
      for (i = 0; i < x.length; i++) {
        (x[i] as HTMLElement).style.display = "none";
      }
      panel.style.display = "block";

      const tabHeaders = document.getElementsByClassName("tab-heading " + tabIdentifier);
      for (i = 0; i < x.length; i++) {
        tabHeaders[i].className = tabHeaders[i].className.replace(" active", "");
      }
      let activeTab = document.getElementById(panelTitle + "Heading" + tabIdentifier);
      if (activeTab) {
        activeTab.className += " active";
      }
    }
  }

  /**
   * Set reference for a button element in a React component.
   */
  static setRef() {
    return React.createRef<HTMLButtonElement>();
  }

  /**
   * Handle button focus when a sidebar button is clicked. When a button is first clicked, it will turn blue (active),
   * after which it will turn grey (selected) if anything else is clicked.
   */
  static handleButtonFocus(id: string) {
    const button = document.getElementById(id);
    if (button) {
      const appButtons = document.getElementsByClassName("theia-TreeNode skills-network");
      // Get rid of any active or selected buttons
      for (let i = 0; i < appButtons.length; i++) {
        appButtons[i].className = appButtons[i].className.replace(" selected", "");
        appButtons[i].className = appButtons[i].className.replace(" active", "");
      }

      // Set current button as active (blue)
      button.className += " active";

      const onClickOutside = (e: MouseEvent) => {
        if (!(e.target as Element).className.includes("theia-TreeNode skills-network active")) {
          // Change button state from active (blue) to selected (light grey)
          button.className = button.className.replace(" active", " selected");
          // Dispose of event listener
          window.removeEventListener("click", onClickOutside);
        }
      };

      // Add event listener that will trigger if anything else is clicked
      window.addEventListener("click", onClickOutside);
    } else {
      LoggerManager.getInstance()?.info(id + " button is null")
    }
  }

}
