import { CommandRegistry, MessageService } from '@theia/core';
import { Disposable, DisposableCollection } from '@theia/core/lib/common/disposable';
import React = require('react');
import { HelperService } from '../helper-service';
import { Status } from "../tab-page/Status";

/**
 * Sidebar button props for applications.
 */
export interface SidebarAppButtonProps {
  name: string;
  status: Status;
  appId: string;
  subtitle?: string;
  description: string;
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  messageService: MessageService;
  commandReg: CommandRegistry;
}

interface SidebarAppButtonState {
  status: Status
}

export class SidebarAppButton extends React.Component<SidebarAppButtonProps, SidebarAppButtonState> {

  constructor(props: SidebarAppButtonProps) {
    super(props);

    this.state = {
      status: this.props.status
    };

    const setState = this.setState.bind(this);
    this.setState = newState => {
      if (!this.toDisposeOnUnmount.disposed) {
          setState(newState);
      }
    };
  }

  protected readonly toDisposeOnUnmount = new DisposableCollection();

  componentDidMount(): void {
      this.toDisposeOnUnmount.push(Disposable.create(() => { /* mark as mounted */ }));
  }
  componentWillUnmount(): void {
      this.toDisposeOnUnmount.dispose();
  }

  public changeStatus = (newStatus: Status) => this.setState({
    status: newStatus
  });

  get status(): Status {
    return this.props.status;
  }

  render(): JSX.Element {
    return <React.Fragment>
      <div onClick={() => this.handleClick()}>
        <div className={"theia-TreeNode skills-network"}
        style={ (!this.props.onClick) ? {cursor: 'default', color: 'var(--theia-secondaryButton-disabledForeground)'} : {} }
        id={this.props.appId} title={this.props.description} onClick={this.props.onClick}>

          <div className="theia-TreeNodeContent">
            <div className="noWrapInfo">
              <span className="app-name">{this.props.name}</span>
              <span className="app-status" style={{color: Status.getColor(this.state.status)}}>
                {(this.props.subtitle) ? this.props.subtitle : Status.getTitle(this.state.status)}
              </span>
            </div>
          </div>

        </div>
      </div>
    </React.Fragment>
  }

  protected handleClick() {
    if (this.props.status === Status.DISABLED && !this.props.subtitle) {
      this.props.messageService.warn("This feature is currently disabled. To enable it, please select either option \
      to switch to a compatible Cloud IDE environment in a new tab.", "Kubernetes", "OpenShift")
        .then(env => env && this.switchEnvironments(env));
    }
    if (this.props.onClick) {
      HelperService.handleButtonFocus(this.props.appId);
    }
  }

  protected switchEnvironments(env: string) {
    this.props.commandReg.executeCommand('security-warning:command', env);
  }

}
