import React = require('react');
import { HelperService } from '../../../../helper-service';
import { TheiaServices } from '../../../tab-page-widget';
import { Status } from "../../../Status";
import { CopyText } from '../../copy-text';
import { AccessButtons } from '../../access-buttons';
import { LinkButton } from '../../link-button';
import { ApplicationInfo } from '../../../database-tab';


module.exports = {
  render: function (app: ApplicationInfo, theia: TheiaServices, status: Status):
  JSX.Element {

    // Define an initial prompt based on the application status.
    let prompt: JSX.Element;

    switch (status) {
      case Status.INACTIVE:
        prompt = <p>Get started with {app.name} in a faster, easier way. To launch your {app.category}, hit the
        Start button.</p>
        break;
      case Status.DISABLED:
        prompt = <div>
          <p>Get started with {app.name} in a faster, easier way. To launch your {app.category}, hit the
            Start button.
          </p>
          <p>This feature is disabled in this specific Cloud IDE environment. To view your project or course
            instructions in a compatible environment, click on <b>Open Cloud IDE with Docker</b> or <b>Open Cloud IDE with
            OpenShift</b> under Other. Doing so will allow you to pick up your progress in a new browser tab and
            utilize an enabled {app.name}.
          </p>
        </div>
        break;
      case Status.STARTING:
        prompt = <p>Starting your {app.category}. This process can take up to a minute.</p>
        break;
      case Status.ACTIVE:
        let webAdminPrompt: string;
        webAdminPrompt = app.webAdminName ? ("and " + app.webAdminName + " server are") : ("server is");
        prompt = <p>Your {app.category} {webAdminPrompt} now ready to use and available with the following login
          credentials. For more details on how to navigate {app.name}, please check out the Details section.</p>
        break;
      case Status.STOPPING:
        prompt = <p>Stopping your {app.category}. Please give us a moment.</p>
        break;
      case Status.RESTORING:
        prompt = <p>Restoring your connection. Please give us a moment.</p>
        break;
      default: // error
        prompt = <p>For more information on why this may have occurred, please refer to this article <a target="_blank"
          href={app.supportLink}>
          here.</a> If you are unable to resolve the issue, please click the Support/Feedback tab on the right-hand
          side of your screen to open a support ticket.</p>
        break;
    }

    // Display informative messages when the tool is starting
    let progress: JSX.Element;
    let elem = document.getElementById("progress-message");
    let counter = 0;
    let interval = setInterval(changeProgressMessage, 5000);

    progress = <h3 id="progress-message"></h3>

    function changeProgressMessage() {
      if (status != Status.STARTING) return;

      if (elem != null && status === Status.STARTING) {
        elem.innerHTML = app.loadingMessages[counter++ % app.loadingMessages.length];
      }
    }

    if (status === Status.ACTIVE) {
      clearInterval(interval);
      progress = <p id="progress-message"></p>
    }

     // For each credential that needs to be displayed in the Summary panel, create a copy text container.
     let copyContainers: JSX.Element[] = [];
     if ((Status.showTabPanelContent(status)) && app.summaryCredentials) {
       Object.entries(app.summaryCredentials).forEach((entry: any) => {
         // Why is applicationId={app.id + "1"}? Since these credentials are also displayed in the Connection Information
         // panel, we need to ensure that the copy container id displayed here is also unique. TLDR: prevents copy error bug.
         copyContainers.push(
           <CopyText key={entry[0]} status={status} label={entry[0]} value={entry[1]} applicationId={app.id + "1"}
             messageService={theia.messageService} />
         );
       })
     }
 
    // Display buttons to access the web admin tool if the application has one.
    let webAdminAccess: JSX.Element[] = [];
    if (app.webAdminName && (Status.showTabPanelContent(status)) && app.connectionInformation) {
      webAdminAccess.push(<p key={"adminPrompt"} style={{marginTop: 0}}>You can manage {app.name} via:</p>);
      webAdminAccess.push(
        <LinkButton key={"webAdmin"} title={app.webAdminName} internalRef={HelperService.setRef()} externalRef={HelperService.setRef()}
          appShell={theia.appShell} varResolver={theia.varResolver} miniBrowserHandler={theia.miniBrowserHandler}
          messageService={theia.messageService} windowService={theia.windowService}
          url={app.connectionInformation["URL"]} status={status} />
      );
    }

    // Display buttons to interact with the application in the terminal.
    let terminalAccess: JSX.Element[] = [];
    let terminalPrompt: string;
    // Check that this application has a shell, connection info is loaded, and for a loading or active status.
    if (app.shellName && app.name && app.connectionInformation && (Status.showTabPanelContent(status))) {
      if (webAdminAccess && webAdminAccess.length) { // If the application has a web admin tool
        terminalPrompt = "Or to interact with the database in the terminal, select one of these options:";
      } else { // Otherwise
        terminalPrompt = "To interact with the database in the terminal, select one of these options:";
      }
      terminalAccess.push(<p key={"terminalPrompt"} style={{ marginTop: 0 }}>{terminalPrompt}</p>);
      terminalAccess.push(
        <AccessButtons key={"terminalButtons"} status={status} cliName={app.shellName} appName={app.name}
          terminalService={theia.terminalService} messageService={theia.messageService}
          startCommand={app.connectionInformation[app.name + " CLI Command"]} />
      )
    }

    // Render generated stuff
    return (<div>
      <div>
        {progress}
      </div>

      <div>
        {prompt}
      </div>

      {/* summary login credentials */}
      <div className="generated-info-container">
        {copyContainers}
      </div>

      {/* buttons to interact with application */}
      <div>
        {webAdminAccess}
      </div>

      <div>
        {terminalAccess}
      </div>

    </div>)
  }

}
