import { TabPageWidget } from "./tab-page-widget";
import * as React from "react";
import { Autocomplete } from "@material-ui/lab";
import { createTheme, TextField, ThemeProvider } from "@material-ui/core";
import { LinkButton } from "./components/link-button";
import { AlertMessage } from "@theia/core/lib/browser/widgets/alert-message";
import { Status } from "./Status";
import { HelperService } from "../helper-service";
import { LoggerManager } from "../managers/logger-manager";
import { Message } from "@theia/core/lib/browser";


export class LaunchApplicationTab extends TabPageWidget {

  static readonly childID = 'launch-application-tab:widget';

  launchApplicationUrl: string;
  launchApplicationPort: string;
  applicationPorts: { title: string; value: string; }[] = [];
  internalButtonRef: React.RefObject<HTMLButtonElement>;
  externalButtonRef: React.RefObject<HTMLButtonElement>;

  constructor() {
    super();
    LoggerManager.getInstance({backend: this.backendService})?.info("LaunchApplicationTab is being constructed");
    this.internalButtonRef = HelperService.setRef();
    this.externalButtonRef = HelperService.setRef();
  }

  /**
   * Updates the tab to reflect a change in launch application ports
   */
  public async resetApplicationPorts(updatedApplicationPorts: any): Promise<void> {
    this.applicationPorts = updatedApplicationPorts;
    // ReactDOM.render(<React.Fragment>{this.render()}</React.Fragment>, this.node, () => this.onRender.dispose());
  }

  /**
   * Overrides abstract render() method in TabPageWidget.
   */
  protected render(): React.ReactNode {
    return (<div id='tab-container-with-padding'>
      <div className="title-container">
        <h1>Launch Your Application</h1>
      </div>
      <hr />
      <AlertMessage type='INFO' header="To open any application in the browser, please select or enter the port number below." />
      <form name="portForm" onSubmit={async (e) => {
        e.preventDefault();
        // Close this tab.
        this.appShell.closeWidget(this.id);
        // Give focus to recently opened mini browser or last active tab in main area.
        this.appShell.activatePreviousTabInTabBar(this.appShell.getTabBarFor("main"));
      }}>
        <ThemeProvider theme={this.theme}>
          <Autocomplete
            freeSolo
            forcePopupIcon
            id="combo-box"
            options={this.applicationPorts}
            // @ts-ignore
            getOptionLabel={(option) => option.title || option}
            style={{
              width: 180,
              color: "blue",
              textAlign: "center",
              marginBottom: '20px',
              marginLeft: 0,
              marginRight: 15,
              padding: "8px 8px 8px 0"
            }}
            onInputChange={async (e, value) => this.handleChange(e, value)}
            renderInput={(params) => <TextField
              {...params}
              InputLabelProps={{ style: { color: 'var(--theia-foreground)', fontSize: '13px' } }}
              label="Application Port"
              InputProps={{ ...params.InputProps, style: { color: 'var(--theia-foreground)' } }}
              className="button-container autocomplete" />}
          />
        </ThemeProvider>
        <div className="button-container">
          <LinkButton title="Your Application" internalRef={this.internalButtonRef}
            externalRef={this.externalButtonRef} appShell={this.appShell}
            varResolver={this.varResolver} miniBrowserHandler={this.miniBrowserHandler} messageService={this.messageService}
            windowService={this.windowService} url={(this.launchApplicationUrl)} status={Status.ACTIVE} />
        </div>
      </form>
    </div>)
  }

  protected async handleChange(_e: React.ChangeEvent<{}>, value: string) {
    // Set application port to inputted value.
    this.launchApplicationPort = value;
    // Enable or disable Launch button based on empty input or not.
    const internalButton = this.internalButtonRef.current;
    const externalButton = this.externalButtonRef.current;
    if (value && internalButton && externalButton) {
      internalButton.disabled = false;
      externalButton.disabled = false;
      // Set launchApplicationUrl to the inputted port value.
      await this.setUrlWithPort();
    } else if (internalButton && externalButton) {
      internalButton.disabled = true;
      externalButton.disabled = true;
    } else {
      LoggerManager.getInstance({backend: this.backendService})?.info(`handleChange: LinkButton button ref was undefined - value ${value}`);
    }
  }

  /**
   * Helper function to set application URL from the current port URL (which is set in handleChange).
   */
  private async setUrlWithPort(): Promise<void> {
    let currentPort = this.launchApplicationPort;
    this.applicationPorts.forEach(dbs => {
      if (dbs.title == currentPort) {
        currentPort = dbs.value;
      }
    })
    this.launchApplicationUrl = await this.backendService.getLaunchApplicationURL(currentPort);
    // ReactDOM.render(<React.Fragment>{this.render()}</React.Fragment>, this.node, () => this.onRender.dispose());
    this.update();
  }

  onFirstActivateRequest(): void {
    super.onFirstActivateRequest();
    this.disableLinkButton();
  }

  onAfterAttach(msg: Message): void {
    super.onAfterAttach(msg);
    this.disableLinkButton();
  }

  private disableLinkButton(): void {
    const internalButton = this.internalButtonRef.current;
    const externalButton = this.externalButtonRef.current;
    if (internalButton && externalButton) {
      internalButton.disabled = true;
      externalButton.disabled = true;
    } else {
      LoggerManager.getInstance({backend: this.backendService})?.info("disableLinkButton - LinkButton button ref was undefined");
    }
  }

  readonly theme = createTheme({
    overrides: {
      MuiPaper: {
        root: {
          color: 'var(--theia-sideBarSectionHeader-foreground)',
          backgroundColor: 'var(--theia-sideBar-background)'
        }
      }
    }
  })

}
