import { Environment } from "./environment";

export const BackendService = Symbol('HelloBackendService');
export const BACKEND_PATH = '/services/BackendService';

export interface BackendService {
  startApplication(appId: string): Promise<any>
  stopApplication(appId: string): Promise<any>
  isApplicationUp(appId: string): Promise<any>
  getLaunchApplicationURL(port: string): Promise<string>
  getOpenApplications(): Promise<any>
  addApplicationPort(applicationName: string | undefined,
                     applicationPort: string | undefined,
                     webEnabled: boolean | undefined) : Promise<any>
  createDirectory(path: string) : void
  getEnvironment(): Environment
  isStaging(): boolean
  getOpenShiftURL(): string
  log_info(message: string, component?: string): void
  log_warn(message: string, component?: string): void
  log_error(message: string, component?: string): void
  log_debug(message: string, component?: string): void
}
