import * as React from 'react';
import * as ReactDOM from 'react-dom';
import { TabPageWidget } from "./tab-page-widget";
import { Status } from "./Status";
import { ApplicationTabPanel } from './components/application-tab-panel';
import { DatabaseSubheading } from './components/database-subheading';
import { Message } from '@theia/core/lib/browser';
import { HelperService } from '../helper-service';
import { ApplicationManager } from '../managers/application-manager';
import { StartButton } from './components/start-button';
import { StopButton } from './components/stop-button';

export interface ApplicationInfo {
  id: string;
  name: string;
  description: string;
  category: string;
  requiredPorts: string[];
  publicPort?: string;
  webEnabled?: boolean;
  webAdminName?: string;
  hasDatabaseServer: boolean;
  startButton?: { [key: string]: string };
  statusPillLabels?: { [key: string]: string };
  tabPanelHeadings?: { [key: string]: string };
  versions?: { [key: string]: string };
  connectionInformation?: { [key: string]: string };
  summaryCredentials?: { [key: string]: string };
  supportLink?: string;
  shellName?: string;
  loadingMessages: string[];
}

export class DatabaseTab extends TabPageWidget {

  static readonly childID = 'application-tab:widget';

  protected appId: string;
  protected status: Status;
  protected applicationInfo: ApplicationInfo;
  protected manager: ApplicationManager;

  set appInfo(info: ApplicationInfo) {
    this.applicationInfo = info;
  }

  set applicationId(id: string) {
    this.appId = id;
  }

  set appStatus(newStatus: Status) {
    this.status = newStatus;
  }

  set appManager(manager: ApplicationManager) {
    this.manager = manager;
  }

  get appStatus(): Status {
    return this.status
  }

  storeState(): object | undefined {
    return {
      appId: this.appId,
      status: this.status,
      applicationInfo: this.applicationInfo,
      tabTitle: this.applicationInfo.name,
      tabId: this.appId,
      icon: this.title.iconClass,
    };
  }

  restoreState(oldState: object): void {
    const state = oldState as {
      appId: string,
      status: Status,
      applicationInfo: ApplicationInfo,
      tabTitle: string,
      tabId: string,
      icon: string,
    };
    this.appId = state.appId;
    this.status = state.status;
    this.applicationInfo = state.applicationInfo;
    this.title.label = state.tabTitle;
    this.id = state.tabId;
    this.title.iconClass = state.icon;
    this.manager = ApplicationManager.getInstance({
      backend: this.backendService,
      shell: this.appShell,
      messaging: this.messageService,
      varResolver: this.varResolver,
      window: this.windowService
    });
    // Based on the status saved, do stuff (matches restoreState() in SkillsNetworkWidget)
    switch (state.status) {
      // STARTING/STOPPING => throw Error status
      case Status.STARTING:
      case Status.STOPPING:
        this.appStatus = Status.ERROR;
        break;
      // ACTIVE => change state temporarily to restoring (handled in SkillsNetworkWidget)
      case Status.ACTIVE:
        this.appStatus = Status.RESTORING;
        break;
      // INACTIVE, ERROR, RESTORING => do nothing
      default:
        break;
    }
  }

  /**
   * Updates the tab to reflect a change in database status.
   */
  public async reloadTab(newStatus: Status): Promise<void> {
    this.appStatus = newStatus;
    // ReactDOM.render(<React.Fragment>{this.render()}</React.Fragment>, this.node, () => this.onRender.dispose());
    ReactDOM.render(<React.Fragment>{this.render()}</React.Fragment>, this.node);

  }

  /**
   * Overrides abstract render() method in TabPageWidget.
   */
  protected render(): React.ReactNode {
    return (<div id='tab-container'>
      {/* HEADER */}
      <div className="sn-tool-header">
        <div className="title-container">
          <h1>{this.applicationInfo.name}</h1>
          <span className="status-pill" style={{ color: Status.getColor(this.status) }} title="Status">
            {Status.getTitle(this.status, this.applicationInfo.statusPillLabels)}
          </span>
        </div>
        <DatabaseSubheading appId={this.appId}
          hasAdminApp={(this.applicationInfo.webAdminName ? true : false)} 
          hasDatabaseServer={this.applicationInfo.hasDatabaseServer}
          versionDict={this.applicationInfo.versions} description={this.applicationInfo.description} />
        <div className="flex flex-row">
          <StartButton id={this.appId} name={this.applicationInfo.name} status={this.status} manager={this.manager}
            altButtonText={this.applicationInfo.startButton} />
          <StopButton id={this.appId} name={this.applicationInfo.name} status={this.status} manager={this.manager}
            altButtonText={this.applicationInfo.startButton} />
        </div>
      </div>

      {/* TAB PANEL NAVIGATION */}
      <div className="tabbed-navigation">
        <button className={"tab-heading " + this.appId + " active"} id={"SummaryHeading" + this.appId}
          onClick={() => HelperService.openTabPanel("Summary", this.appId)}>
            <p>{(this.applicationInfo.tabPanelHeadings?.summary || "Summary")}</p></button>
        <button className={"tab-heading " + this.appId} id={"ConnectionInformationHeading" + this.appId}
          onClick={() => HelperService.openTabPanel("ConnectionInformation", this.appId)}>
            <p>{(this.applicationInfo.tabPanelHeadings?.connectionInformation || "Connection Information")}</p></button>
        <button className={"tab-heading " + this.appId} id={"DetailsHeading" + this.appId}
          onClick={() => HelperService.openTabPanel("Details", this.appId)}>
            <p>{(this.applicationInfo.tabPanelHeadings?.details || "Details")}</p></button>
      </div>

      {/* SUMMARY PANEL */}
      <div id={"Summary" + this.appId} className={"tab-panel " + this.appId}>
        <ApplicationTabPanel panelHeading="summary" applicationInfo={this.applicationInfo}
          theiaServices={this.theiaServices} status={this.status} />
      </div>

      {/* CONNECTION INFORMATION PANEL */}
      <div id={"ConnectionInformation" + this.appId} className={"tab-panel " + this.appId} style={{ display: 'none' }}>
        <ApplicationTabPanel panelHeading="connectioninformation" applicationInfo={this.applicationInfo}
          theiaServices={this.theiaServices} status={this.status} />
      </div>

      {/* DETAILS PANEL */}
      <div id={"Details" + this.appId} className={"tab-panel " + this.appId} style={{ display: 'none' }}>
        <ApplicationTabPanel panelHeading="details" applicationInfo={this.applicationInfo}
          theiaServices={this.theiaServices} status={this.status} />
      </div>

    </div>)
  }

  /** Before closing, change state if appropriate. */
  protected onCloseRequest(msg: Message): void {
    this.manager.onCloseTab(this.appId, this.status);
    super.onCloseRequest(msg);
  }

}
